/// Moving indicators, unless `tui.animations` is off or the environment
/// asks for reduced motion (`REDUCED_MOTION` / `FORMLESS_REDUCED_MOTION`
/// set to anything but empty, `0`, `false` or `off`).
fn animations_enabled(setting: bool) -> bool {
    let reduced = ["FORMLESS_REDUCED_MOTION", "REDUCED_MOTION"]
        .iter()
        .any(|k| {
            std::env::var(k).is_ok_and(|v| {
                !matches!(
                    v.trim().to_ascii_lowercase().as_str(),
                    "" | "0" | "false" | "off" | "no"
                )
            })
        });
    setting && !reduced
}

/// Synchronize the terminal effect at startup and after live settings events.
/// Remember only successful writes, so a transient output error can recover.
#[derive(Default)]
struct MotionCursor {
    applied: Option<bool>,
}

impl MotionCursor {
    fn sync(&mut self, out: &mut impl Write, animations: bool) -> std::io::Result<()> {
        if self.applied != Some(animations) {
            out.execute(if animations {
                crossterm::cursor::SetCursorStyle::DefaultUserShape
            } else {
                crossterm::cursor::SetCursorStyle::SteadyBar
            })?;
            self.applied = Some(animations);
        }
        Ok(())
    }
}

const SPINNER: [&str; 10] = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];

/// Multi-pane layout is active only when persisted on and wide enough.
pub(crate) fn pane_layout(multi_pane: bool, width: u16) -> bool {
    multi_pane && width >= 110
}

fn colors_enabled() -> bool {
    std::env::var_os("NO_COLOR").is_none_or(|value| value.is_empty())
}

fn fg(enabled: bool, color: Color) -> Style {
    if enabled {
        Style::default().fg(theme::remap(color))
    } else {
        Style::default()
    }
}

fn bold_fg(enabled: bool, color: Color) -> Style {
    fg(enabled, color).add_modifier(Modifier::BOLD)
}

fn role_style(enabled: bool, role: &str) -> Style {
    let (name, color) = match role {
        "user" => ("user", Color::Cyan),
        "tool" => ("tool", Color::Yellow),
        "system-note" => ("note", Color::Blue),
        _ => ("assistant", Color::Green),
    };
    match theme::role(name).filter(|_| enabled) {
        // Already resolved through the role palette; avoid accent/error chaining.
        Some(c) => Style::default().fg(c).add_modifier(Modifier::BOLD),
        None => bold_fg(enabled, color),
    }
}

fn thinking_style(enabled: bool) -> Style {
    fg(enabled, Color::Magenta).add_modifier(Modifier::ITALIC | Modifier::DIM)
}

fn format_elapsed(d: Duration) -> String {
    let s = d.as_secs();
    if s < 60 {
        format!("{s}s")
    } else {
        format!("{}m{:02}s", s / 60, s % 60)
    }
}

fn format_live_elapsed(d: Duration) -> String {
    let s = d.as_secs();
    if s < 3600 {
        format_elapsed(d)
    } else {
        format!("{}h{:02}m{:02}s", s / 3600, s % 3600 / 60, s % 60)
    }
}

fn format_recorded_duration(ms: u64) -> String {
    match ms {
        0 => "0s".into(),
        1..=999 => format!("{ms}ms"),
        1000..=59_999 if ms / 100 % 10 != 0 => format!("{}.{}s", ms / 1000, ms / 100 % 10),
        _ => format_live_elapsed(Duration::from_millis(ms)),
    }
}

#[cfg(test)]
#[test]
fn recorded_invocation_durations_keep_short_and_long_times_readable() {
    for (ms, expected) in [
        (0, "0s"),
        (499, "499ms"),
        (1000, "1s"),
        (1175, "1.1s"),
        (59_999, "59.9s"),
        (60_000, "1m00s"),
        (3_600_000, "1h00m00s"),
        (7_200_000, "2h00m00s"),
    ] {
        assert_eq!(format_recorded_duration(ms), expected);
    }
}

