/// Pasted search queries stay on one line without joining separate words.
fn single_line_query_paste(text: &str) -> String {
    text.replace("\r\n", "\n")
        .replace(['\r', '\n'], " ")
        .chars()
        .filter(|c| !c.is_control())
        .collect()
}

