/// An open `ask_user` call (SPEC §5.5); `answers` fills as the user
/// answers its questions in order.
struct OpenQuestion {
    id: String,
    session_id: String,
    questions: Vec<Question>,
    answers: Vec<QuestionAnswer>,
    /// The highlighted row of the current question: an option, or
    /// `options.len()` for "Other…".
    cursor: usize,
    /// Ticked options of a multi-select question.
    checked: Vec<bool>,
    /// The Formless model may not answer this one.
    user_only: bool,
}

impl OpenQuestion {
    fn new(id: String, session_id: String, questions: Vec<Question>) -> Self {
        let mut q = OpenQuestion {
            id,
            session_id,
            questions,
            answers: Vec::new(),
            cursor: 0,
            checked: Vec::new(),
            user_only: false,
        };
        q.reset_choice();
        q
    }

    fn current(&self) -> &Question {
        &self.questions[self.answers.len()]
    }

    /// Fresh cursor and ticks for the current question.
    fn reset_choice(&mut self) {
        self.cursor = 0;
        self.checked = vec![false; self.current().options.len()];
    }

    fn on_other(&self) -> bool {
        self.cursor >= self.current().options.len()
    }

    /// The answer the panel's selection gives: the ticked options (or the
    /// highlighted one), None on "Other…".
    fn picked(&self) -> Option<QuestionAnswer> {
        let q = self.current();
        let mut selected: Vec<String> = q
            .options
            .iter()
            .zip(&self.checked)
            .filter(|(_, c)| **c)
            .map(|(o, _)| o.label.clone())
            .collect();
        if selected.is_empty() {
            selected.push(q.options.get(self.cursor)?.label.clone());
        }
        Some(QuestionAnswer {
            selected,
            text: None,
        })
    }

    /// The chat note for the next unanswered question.
    fn prompt(&self) -> String {
        let n = self.answers.len();
        let q = &self.questions[n];
        let mut text = String::from("question");
        if self.questions.len() > 1 {
            text.push_str(&format!(" {}/{}", n + 1, self.questions.len()));
        }
        if let Some(h) = &q.header {
            text.push_str(&format!(" [{h}]"));
        }
        text.push_str(&format!(": {}", q.question));
        for (i, o) in q.options.iter().enumerate() {
            text.push_str(&format!("\n  {}) {}", i + 1, o.label));
            if let Some(d) = &o.description {
                text.push_str(&format!(" — {d}"));
            }
        }
        text.push_str(match (q.options.is_empty(), q.multi_select) {
            (true, _) => "\n  type your answer and press Enter",
            (false, false) => "\n  type an option number or your own answer and press Enter",
            (false, true) => {
                "\n  type option numbers (e.g. 1,3) or your own answer and press Enter"
            }
        });
        text
    }
}

#[derive(Clone)]
struct ApprovalReq {
    context: Option<formless_protocol::ApprovalContext>,
    approval_id: String,
    tool_name: String,
    version: i64,
    capabilities: Vec<String>,
    memory_mb: u32,
    /// What exactly is being approved, for non-Tool approvals.
    detail: Option<String>,
    /// Capabilities already granted (the rest are new).
    already_allowed: Vec<String>,
    code_preview: Option<String>,
    /// The Tool behind it, for `v` (its full code).
    tool_id: Option<String>,
    /// The Session whose Run asked.
    session_id: Option<String>,
}

fn approval_inspection_lines(req: &ApprovalReq, summary: Option<&str>) -> Vec<String> {
    use text::escape_approval_controls as approval_text;

    let mut lines = vec![
        format!("Tool {} v{}", approval_text(&req.tool_name), req.version),
        format!("Memory: {} MB", req.memory_mb),
        "Capabilities requested:".into(),
    ];
    for capability in &req.capabilities {
        lines.push(format!(
            "  {}{}",
            approval_text(capability),
            if req.already_allowed.contains(capability) {
                " (already allowed)"
            } else {
                ""
            }
        ));
        if let Some(warning) = formless_protocol::sensitive_read_warning(capability) {
            lines.push(format!("  ⚠ {warning}"));
        }
    }
    if let Some(session) = &req.session_id {
        lines.push(format!("Session: {}", approval_text(session)));
    }
    if let Some(summary) = summary {
        lines.push(format!("AI summary (may be wrong): {summary}"));
    }
    if let Some(detail) = &req.detail {
        lines.push("Approval details:".into());
        lines.extend(detail.lines().map(|line| approval_text(line).into_owned()));
    }
    if let Some(context) = &req.context {
        if let Some(run) = &context.run_id {
            lines.push(format!("Run: {}", approval_text(run)));
        }
        lines.extend(
            formless_protocol::approval_context_lines(context)
                .into_iter()
                .map(|line| approval_text(&line).into_owned()),
        );
    } else {
        lines.push("This daemon did not supply call/source evidence.".into());
    }
    if let Some(code) = &req.code_preview {
        lines.push("Code preview for this approval (first lines):".into());
        lines.extend(code.lines().map(|line| approval_text(line).into_owned()));
    }
    lines.push(
        "Close this inspector, then v to fetch the full Tool code for the approval version.".into(),
    );
    lines
        .into_iter()
        .map(|line| text::escape_bidi(&line).into_owned())
        .collect()
}

