enum WizardKeyUpdate {
    Preserve,
    Save(String),
    ConfirmClear,
}

#[derive(Debug, PartialEq, Clone, Copy)]
enum WizardStep {
    /// Choose a provider preset (or Custom URL).
    PickPreset,
    BaseUrl,
    ApiKey,
    FetchModels,
    PickModel,
    PickEffort,
    Probing,
    Failed,
}

struct Wizard {
    profile: String,
    setup_hint: Option<String>,
    step: WizardStep,
    /// Highlighted row in `PickPreset`: a preset, or `PRESETS.len()` for
    /// a custom URL.
    preset_idx: usize,
    preset: Option<&'static formless_core::presets::Preset>,
    /// A failed model fetch from a local server: Enter retries it.
    retry_fetch: bool,
    base_url: String,
    api_key: String,
    picker: picker::ModelPicker,
    effort_idx: usize,
    status: String,
    /// Previously saved model, pre-selected when the list arrives (§17).
    saved_model: String,
    prompt_fallback: bool,
    /// What the probe saw: false when the endpoint answered without
    /// streaming (#622).
    streaming: bool,
    /// Ctrl+R: show the API key in full while typing it.
    reveal_key: bool,
    reveal_until: Option<Instant>,
    generation: u64,
    local_pending: bool,
    local_offers: Vec<formless_core::local_servers::LocalServer>,
    /// Endpoint under which the current key/model were entered.
    credential_endpoint: String,
    /// Only an explicitly re-opened setup can return to an existing Session.
    can_cancel: bool,
    confirm_key_change: bool,
    key_change_confirmed: bool,
    draft_changed: Option<Instant>,
    saved_draft: Option<serde_json::Value>,
    jobs: mpsc::Receiver<WizardJob>,
    job_tx: mpsc::Sender<WizardJob>,
}

const EFFORTS: [Option<&str>; 4] = [None, Some("low"), Some("medium"), Some("high")];
const KEY_REVEAL_TIME: Duration = Duration::from_secs(10);
const WIZARD_DRAFT_DELAY: Duration = Duration::from_millis(300);

impl Wizard {
    fn new(cfg: &Config) -> Self {
        let (job_tx, jobs) = mpsc::channel();
        // Remember previous startup options: a saved config starts at the
        // API-key step (Esc returns to the URL), with model/effort restored.
        let has_saved = !cfg.provider.base_url.trim().is_empty();
        let preset = formless_core::presets::for_provider(&cfg.provider);
        let (step, status) = if has_saved {
            (
                WizardStep::ApiKey,
                tr("Saved setup found. Enter a replacement API key, or press Enter to reuse its stored key when available (Esc to choose another provider).").into(),
            )
        } else {
            (
                WizardStep::PickPreset,
                tr("Welcome to Formless. Choose your model provider.").into(),
            )
        };
        let preset_idx = preset
            .and_then(|p| {
                formless_core::presets::PRESETS
                    .iter()
                    .position(|x| x.id == p.id)
            })
            .unwrap_or(0);
        let effort_idx = cfg
            .provider
            .reasoning_effort
            .as_deref()
            .and_then(|e| EFFORTS.iter().position(|x| *x == Some(e)))
            .unwrap_or(0);
        Self {
            profile: "default".into(),
            setup_hint: None,
            step,
            preset_idx,
            preset,
            retry_fetch: false,
            base_url: cfg.provider.base_url.clone(),
            api_key: String::new(),
            picker: picker::ModelPicker::loading(),
            effort_idx,
            status,
            saved_model: cfg.provider.model.clone(),
            prompt_fallback: false,
            streaming: true,
            reveal_key: false,
            reveal_until: None,
            generation: 0,
            local_pending: false,
            local_offers: Vec::new(),
            credential_endpoint: cfg.provider.base_url.trim().to_string(),
            can_cancel: false,
            confirm_key_change: false,
            key_change_confirmed: false,
            draft_changed: None,
            saved_draft: None,
            jobs,
            job_tx,
        }
    }

    /// Profile context is discovered once, never during frame rendering.
    fn new_for_profile(cfg: &Config, paths: &Paths) -> Self {
        let mut w = Self::new(cfg);
        w.profile = paths.profile.clone();
        if !cfg.provider.is_configured() {
            w.setup_hint = formless_core::profile_setup::alternate_setup_hint(paths)
                .map(|hint| tr_format("This profile needs setup. {}", &[&hint]));
        }
        w
    }

    /// Resume a draft, or offer an already running local server.
    fn start(cfg: &Config, paths: &Paths) -> Self {
        Self::start_with_discovery(
            cfg,
            paths,
            formless_core::local_servers::discover_with_guidance,
        )
    }

    #[cfg(test)]
    fn start_with_detector(
        cfg: &Config,
        paths: &Paths,
        detect: impl FnOnce() -> Vec<formless_core::local_servers::LocalServer> + Send + 'static,
    ) -> Self {
        Self::start_with_discovery(cfg, paths, move || detect().into())
    }

    fn start_with_discovery(
        cfg: &Config,
        paths: &Paths,
        detect: impl FnOnce() -> formless_core::local_servers::Discovery + Send + 'static,
    ) -> Self {
        let mut w = Self::new_for_profile(cfg, paths);
        if w.step != WizardStep::PickPreset {
            return w;
        }
        if let Some(d) = load_wizard_draft(paths).filter(|d| d["step"] != "preset") {
            w.resume(&d);
            return w;
        }
        w.offer_local_with(detect);
        w
    }

    /// Pick up a quit wizard where it was; the key is never saved, so a
    /// later step resumes at the key.
    fn resume(&mut self, d: &serde_json::Value) {
        let preset = d["preset"].as_str().and_then(formless_core::presets::find);
        self.preset = preset;
        if let Some(p) = preset {
            self.preset_idx = formless_core::presets::PRESETS
                .iter()
                .position(|x| x.id == p.id)
                .unwrap_or(0);
        } else if d["custom"] == true {
            self.preset_idx = formless_core::presets::PRESETS.len();
        }
        self.base_url = d["base_url"].as_str().unwrap_or_default().to_string();
        self.credential_endpoint = self.base_url.trim().to_string();
        if let Some(m) = d["model"].as_str().filter(|m| !m.is_empty()) {
            self.saved_model = m.to_string();
        }
        self.effort_idx = d["effort_idx"].as_u64().unwrap_or(0) as usize % EFFORTS.len();
        let local = preset.is_some_and(|p| p.local);
        match d["step"].as_str() {
            Some("base_url") => {
                self.step = WizardStep::BaseUrl;
                self.status = tr("Welcome back. Enter your provider base URL.").into();
            }
            Some("api_key" | "model" | "effort") if local => {
                self.retry_fetch = true;
                self.fetch_models();
            }
            Some("api_key" | "model" | "effort") if !self.base_url.is_empty() => {
                self.enter_api_key_step();
                self.status = tr_format(
                    "Welcome back: you were setting up {}. {}",
                    &[&self.base_url, &self.status],
                );
            }
            _ => {}
        }
    }

    /// No saved setup and no key in the environment: offer Ollama or
    /// LM Studio if one is already running here (#398).
    fn offer_local(&mut self) {
        self.offer_local_with(formless_core::local_servers::discover_with_guidance);
    }

    fn offer_local_with(
        &mut self,
        detect: impl FnOnce() -> formless_core::local_servers::Discovery + Send + 'static,
    ) {
        let presets = formless_core::presets::PRESETS;
        if presets
            .iter()
            .any(|p| formless_core::presets::env_key(p).is_some())
        {
            return;
        }
        self.local_pending = true;
        let generation = self.generation;
        let tx = self.job_tx.clone();
        std::thread::spawn(move || {
            let _ = tx.send(WizardJob::Local(generation, detect()));
        });
    }

    /// What to keep if the TUI quits here: never the key.
    fn draft(&self) -> serde_json::Value {
        let step = match self.step {
            WizardStep::PickPreset => "preset",
            WizardStep::BaseUrl => "base_url",
            WizardStep::ApiKey | WizardStep::FetchModels => "api_key",
            WizardStep::PickModel => "model",
            WizardStep::PickEffort | WizardStep::Probing | WizardStep::Failed => "effort",
        };
        serde_json::json!({
            "step": step,
            "preset": self.preset.map(|p| p.id),
            "custom": self.preset.is_none() && self.step != WizardStep::PickPreset,
            "base_url": self.base_url,
            "model": if matches!(self.step, WizardStep::PickModel | WizardStep::PickEffort | WizardStep::Probing | WizardStep::Failed) { self.model() } else { self.saved_model.clone() },
            "effort_idx": self.effort_idx,
        })
    }

    /// The key as shown: `••••abcd`, or in full after Ctrl+R (#396).
    fn shown_key(&self) -> String {
        let key = self.api_key.trim();
        if self.step == WizardStep::ApiKey
            && self.reveal_key
            && self
                .reveal_until
                .is_some_and(|until| Instant::now() < until)
        {
            return key.to_string();
        }
        let n = key.chars().count();
        let visible = 4.min(n / 2);
        let tail: String = key.chars().skip(n - visible).collect();
        if visible > 0 {
            format!("{}{tail}", "•".repeat(n - visible))
        } else {
            "•".repeat(n)
        }
    }
    fn model(&self) -> String {
        self.picker.choice().unwrap_or_default()
    }

    fn hide_key(&mut self) {
        self.reveal_key = false;
        self.reveal_until = None;
    }

    fn invalidate_jobs(&mut self) {
        self.local_pending = false;
        self.generation = self.generation.wrapping_add(1);
        self.hide_key();
        self.confirm_key_change = false;
        self.key_change_confirmed = false;
    }

    fn clear_provider_state(&mut self) {
        self.invalidate_jobs();
        self.api_key.clear();
        self.saved_model.clear();
        self.picker = picker::ModelPicker::loading();
        self.effort_idx = 0;
        self.prompt_fallback = false;
        self.streaming = true;
    }

    /// Trimming is Unicode-aware. Embedded whitespace almost always means a
    /// bad paste; report it before sending a credential to any endpoint.
    fn normalize_key(&mut self) -> bool {
        self.hide_key();
        self.api_key = self.api_key.trim().to_string();
        if self.api_key.chars().any(char::is_whitespace) {
            self.status =
                tr("The API key contains whitespace inside it. Remove it before continuing.")
                    .into();
            false
        } else {
            true
        }
    }

    fn bind_custom_endpoint(&mut self) {
        let endpoint = self.base_url.trim().to_string();
        if endpoint != self.credential_endpoint {
            self.clear_provider_state();
        }
        self.base_url = endpoint.clone();
        self.credential_endpoint = endpoint;
    }

    fn key_update(&self, previous_endpoint: &str, has_credential: bool) -> WizardKeyUpdate {
        let key = self.api_key.trim();
        if !key.is_empty() {
            WizardKeyUpdate::Save(key.to_string())
        } else if previous_endpoint.trim() == self.base_url.trim() || !has_credential {
            WizardKeyUpdate::Preserve
        } else if self.key_change_confirmed {
            WizardKeyUpdate::Save(String::new())
        } else {
            WizardKeyUpdate::ConfirmClear
        }
    }

    /// The API-key step, with the preset's key page and any key found in
    /// the environment.
    fn enter_api_key_step(&mut self) {
        self.hide_key();
        self.step = WizardStep::ApiKey;
        let mut status = tr("Enter your API key (stored in the OS keychain).").to_string();
        if let Some(p) = self.preset {
            if let Some(url) = p.key_url {
                status.push_str(&tr_format(" Get one at {}", &[url]));
            }
            if let Some((var, _)) = formless_core::presets::env_key(p) {
                status = tr_format(
                    "Found ${}: press Enter to use it, or type a different key.",
                    &[var],
                );
            }
        }
        self.status = status;
    }

    fn apply_provider_endpoint(&self, provider: &mut formless_core::config::ProviderCfg) {
        provider.base_url = self.base_url.trim().to_string();
        provider.preset = self.preset.map(|preset| preset.id.to_string());
        if let Some(preset) = self.preset {
            provider.api_style = preset.api_style.to_string();
        }
    }

    /// List the endpoint's models in the background (`FetchModels`).
    fn fetch_models(&mut self) {
        if !self.normalize_key() {
            self.step = WizardStep::ApiKey;
            return;
        }
        self.invalidate_jobs();
        let generation = self.generation;
        self.step = WizardStep::FetchModels;
        self.status = tr_format("Fetching models from {}…", &[self.base_url.trim()]);
        let tx = self.job_tx.clone();
        let mut pcfg = formless_core::config::ProviderCfg::default();
        self.apply_provider_endpoint(&mut pcfg);
        let key = self.api_key.clone();
        std::thread::spawn(move || {
            let _ = tx.send(WizardJob::Models(
                generation,
                list_models_blocking(&pcfg, &key).map_err(|e| e.to_string()),
            ));
        });
    }

    fn local_offer_for(
        &self,
        preset_id: &str,
    ) -> Option<&formless_core::local_servers::LocalServer> {
        self.local_offers
            .iter()
            .filter(|offer| offer.preset_id == preset_id)
            .min_by_key(|offer| offer.models == 0)
    }

    /// Apply the highlighted preset (or go to the custom URL step).
    fn choose_preset(&mut self) {
        let Some(p) = formless_core::presets::PRESETS.get(self.preset_idx) else {
            if self.preset.is_some() {
                self.clear_provider_state();
                self.credential_endpoint.clear();
            }
            self.preset = None;
            self.step = WizardStep::BaseUrl;
            self.status =
                tr("Enter your provider base URL (any OpenAI-compatible endpoint).").into();
            return;
        };
        let endpoint = if p.local
            && self.preset.is_some_and(|old| old.id == p.id)
            && !self.base_url.trim().is_empty()
        {
            self.base_url.trim().to_string()
        } else {
            self.local_offer_for(p.id)
                .map(|offer| offer.base_url.clone())
                .unwrap_or_else(|| p.base_url.to_string())
        };
        if self.preset.map(|old| old.id) != Some(p.id)
            || self.credential_endpoint != endpoint.trim()
        {
            self.clear_provider_state();
        }
        self.preset = Some(p);
        self.base_url = endpoint;
        self.credential_endpoint = self.base_url.trim().to_string();
        if self.saved_model.is_empty() {
            self.saved_model = p.default_model.to_string();
        }
        if p.local {
            // No key; listing models doubles as the reachability check.
            self.api_key.clear();
            self.retry_fetch = true;
            self.fetch_models();
        } else {
            self.enter_api_key_step();
        }
    }
}

#[cfg(test)]
fn wizard_draft_file(paths: &Paths) -> std::path::PathBuf {
    formless_core::setup_draft::file(paths)
}

fn load_wizard_draft(paths: &Paths) -> Option<serde_json::Value> {
    formless_core::setup_draft::load(paths)
}

/// A Tool call waiting in step mode (SPEC §5.9).
#[derive(Clone)]
struct PendingStep {
    step_id: String,
    tool_name: String,
    arguments: String,
    index: usize,
    count: usize,
}

struct Activity {
    label: String,
    since: Instant,
    /// A provider retry: when the next attempt is sent, and "(2/5)".
    retry: Option<(Instant, String)>,
}

struct EditorReview {
    scroll: std::cell::Cell<EditorReviewScroll>,
    diff: String,
    /// "Passes the syntax and smoke checks", or what fails.
    verdict: String,
    ok: bool,
}

#[derive(Clone, Copy, Default)]
struct EditorReviewScroll {
    top: usize,
    rows: usize,
    height: usize,
}
impl EditorReview {
    fn scroll_key(&self, key: KeyEvent) -> bool {
        if !key.modifiers.is_empty() {
            return false;
        }
        let mut scroll = self.scroll.get();
        let max_top = scroll.rows.saturating_sub(scroll.height);
        scroll.top = scroll.top.min(max_top);
        let page = scroll.height.saturating_sub(1).max(1);
        scroll.top = match key.code {
            KeyCode::Up => scroll.top.saturating_sub(1),
            KeyCode::Down => scroll.top.saturating_add(1).min(max_top),
            KeyCode::PageUp => scroll.top.saturating_sub(page),
            KeyCode::PageDown => scroll.top.saturating_add(page).min(max_top),
            KeyCode::Home => 0,
            KeyCode::End => max_top,
            _ => return false,
        };
        self.scroll.set(scroll);
        true
    }
}

struct EditorState {
    viewport: std::cell::Cell<(usize, usize)>,
    draft: Option<input::InputLine>,
    original: Option<String>,
    confirm_exit: bool,
    review_base_version: Option<i64>,
    vim: vim::Vim,
    tool_id: String,
    name: String,
    chars: Vec<char>,
    cursor: usize,
    mode: EditMode,
}

/// What the Tool editor is editing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EditMode {
    Code,
    /// An input to run the Tool with by hand.
    Run,
    Description,
    /// `{"input_schema": …, "output_schema": …}`.
    Schemas,
    /// A shared module's code (`tool_id` holds the module id).
    Module,
}

impl EditorState {
    fn modal_line(&self) -> input::InputLine {
        let mut line = self
            .draft
            .as_ref()
            .map(input::InputLine::projection)
            .unwrap_or_else(|| input::InputLine::from(self.text().as_str()));
        self.sync_modal_line(&mut line);
        line
    }
    fn take_modal_line(&mut self) -> input::InputLine {
        let mut line = self
            .draft
            .take()
            .unwrap_or_else(|| input::InputLine::from(self.text().as_str()));
        self.sync_modal_line(&mut line);
        line
    }
    fn sync_modal_line(&self, line: &mut input::InputLine) {
        let text = self.text();
        if &**line != text.as_str() {
            line.set(&text);
        }
        // Schema/examples and other programmatic replacements can shorten the
        // character buffer before its previous cursor has been synchronized.
        // Clamp before slicing; InputLine then snaps to a grapheme boundary.
        let cursor = self.cursor.min(self.chars.len());
        line.set_modal_cursor(self.chars[..cursor].iter().map(|c| c.len_utf8()).sum());
    }
    fn apply_modal_line(&mut self, line: input::InputLine) {
        self.cursor = line[..line.cursor_byte()].chars().count();
        self.chars = line.chars().collect();
        self.draft = Some(line);
    }
    fn text(&self) -> String {
        self.chars.iter().collect()
    }
    /// The char index of the cluster boundary before/after `i`: the cursor
    /// never rests inside a letter with its marks or an emoji (#784).
    fn cluster_step(&self, i: usize, forward: bool) -> usize {
        use unicode_segmentation::UnicodeSegmentation;
        let text = self.text();
        let mut at = 0;
        for g in text.graphemes(true) {
            let n = g.chars().count();
            if forward && at >= i {
                return at + n;
            }
            if !forward && at + n >= i {
                return at;
            }
            at += n;
        }
        if forward {
            self.chars.len()
        } else {
            0
        }
    }
    fn left(&mut self) {
        self.cursor = self.cluster_step(self.cursor, false);
    }
    fn right(&mut self) {
        self.cursor = self.cluster_step(self.cursor, true).min(self.chars.len());
    }
    fn backspace(&mut self) {
        let start = self.cluster_step(self.cursor, false);
        self.chars.drain(start..self.cursor);
        self.cursor = start;
    }
    fn delete(&mut self) {
        let end = self.cluster_step(self.cursor, true).min(self.chars.len());
        self.chars.drain(self.cursor..end);
    }
    /// The cursor's screen column on its line.
    fn cursor_col(&self) -> usize {
        let cursor = self.cursor.min(self.chars.len());
        let start = self.chars[..cursor]
            .iter()
            .rposition(|c| *c == '\n')
            .map_or(0, |i| i + 1);
        text::width(&self.chars[start..cursor].iter().collect::<String>())
    }
    fn visible_offsets(
        &self,
        cursor: (usize, usize),
        content: (usize, usize),
        size: (usize, usize),
    ) -> (usize, usize) {
        fn reveal(previous: usize, cursor: usize, total: usize, extent: usize) -> usize {
            let extent = extent.max(1);
            let offset = previous.min(total.saturating_sub(extent));
            if cursor < offset {
                cursor
            } else if cursor >= offset.saturating_add(extent) {
                cursor.saturating_sub(extent - 1)
            } else {
                offset
            }
        }
        let (top, left) = self.viewport.get();
        let offsets = (
            reveal(top, cursor.0, content.0, size.0),
            reveal(left, cursor.1, content.1.saturating_add(1), size.1),
        );
        self.viewport.set(offsets);
        offsets
    }
    fn move_vertical(&mut self, down: bool) {
        // Keep the screen column; target line start found by scans.
        let col = self.cursor_col();
        let mut i = self.cursor;
        while i > 0 && self.chars[i - 1] != '\n' {
            i -= 1;
        }
        if down {
            let mut j = self.cursor;
            while j < self.chars.len() && self.chars[j] != '\n' {
                j += 1;
            }
            if j >= self.chars.len() {
                return;
            }
            let start = j + 1;
            let mut end = start;
            while end < self.chars.len() && self.chars[end] != '\n' {
                end += 1;
            }
            self.cursor = self.at_col(start, end, col);
        } else {
            if i == 0 {
                return;
            }
            let prev_end = i - 1;
            let mut start = prev_end;
            while start > 0 && self.chars[start - 1] != '\n' {
                start -= 1;
            }
            self.cursor = self.at_col(start, prev_end, col);
        }
    }
    /// The last cluster boundary in `start..end` at or before `col`.
    fn at_col(&self, start: usize, end: usize, col: usize) -> usize {
        let mut c = start;
        while c < end {
            let next = self.cluster_step(c, true).min(end);
            let w = text::width(&self.chars[start..next].iter().collect::<String>());
            if w > col || next == c {
                break;
            }
            c = next;
        }
        c
    }
}

#[derive(Clone)]
/// A full-screen text viewer (artifact outputs, SPEC §9.6).
struct Pager {
    title: String,
    lines: Vec<String>,
    top: usize,
    /// Columns scrolled to the right (←/→), for wide content.
    left: usize,
    /// Highlighted lines for entries that carry presentation styles.
    styled: Vec<Line<'static>>,
    viewport: pager_view::View,
}

struct LiveToolCall {
    metadata_pending: bool,
    invocation_id: Option<String>,
    name: String,
    /// Tree depth: nested `tools.call`, or a sub-agent under its Tool.
    depth: usize,
    /// The sub-agent this node stands for.
    subagent: Option<String>,
    version: i64,
    arguments: String,
    status: String,
    started: Instant,
    elapsed_ms: Option<i64>,
    /// Invocation handle once the daemon names it (pending or stalled).
    handle: Option<String>,
    /// Seconds without activity, while the daemon flags it stalled.
    stalled_secs: Option<u64>,
    /// The Tool's latest `progress(fraction, label)`.
    progress: Option<(Option<f64>, String)>,
}

/// The live calls to draw, with how many descendants each folds away. A
/// node shows while it or an ancestor is running; under a node that
/// finished successfully its descendants fold into a count.
fn live_tree(calls: &[LiveToolCall]) -> Vec<(&LiveToolCall, usize)> {
    let mut out: Vec<(&LiveToolCall, usize)> = Vec::new();
    // Stack of (depth, running, open) for the current ancestors.
    let mut stack: Vec<(usize, bool, bool)> = Vec::new();
    for c in calls {
        while stack.last().is_some_and(|(d, _, _)| *d >= c.depth) {
            stack.pop();
        }
        let parent_open = stack.last().is_none_or(|(_, _, open)| *open);
        let ancestor_running = stack.iter().any(|(_, running, _)| *running);
        let running = c.status == "running";
        let visible = parent_open && (running || ancestor_running);
        // Children show under running or failed nodes; ok ones fold.
        let open = visible && c.status != "ok";
        if visible {
            out.push((c, 0));
        } else if let Some(idx) = out
            .iter()
            .rposition(|(n, _)| n.depth < c.depth && n.status == "ok")
            .filter(|_| ancestor_running && !parent_open)
        {
            out[idx].1 += 1;
        }
        stack.push((c.depth, running, open));
    }
    out
}

/// Share of a model's prompt tokens served from the provider's cache.
fn cache_hit_text(st: &ModelStatInfo) -> String {
    if st.prompt_tokens > 0 {
        format!(
            "{:.0}%",
            100.0 * st.cached_tokens as f64 / st.prompt_tokens as f64
        )
    } else {
        "-".into()
    }
}

/// One line of a sub-agent transcript (provider-shaped message).
fn subagent_line(m: &serde_json::Value) -> String {
    let role = m["role"].as_str().unwrap_or("?");
    let text = match m["tool_calls"].as_array() {
        Some(calls) => format!(
            "calls {}",
            calls
                .iter()
                .filter_map(|c| c["function"]["name"].as_str())
                .collect::<Vec<_>>()
                .join(", ")
        ),
        None => m["content"].as_str().unwrap_or_default().replace('\n', " "),
    };
    format!("  [{role}] {}", truncate_chars(&text, 120))
}

/// Identifies a rendered streaming prefix without hashing all of it: the
/// stream only grows (or restarts from empty), so its length plus both
/// ends tell one prefix from another.
#[derive(PartialEq)]
struct StreamKey {
    len: usize,
    head: u64,
    tail: u64,
    width: usize,
}

impl StreamKey {
    fn new(prefix: &str, width: usize) -> Self {
        use std::hash::{Hash, Hasher};
        let hash = |bytes: &[u8]| {
            let mut h = std::collections::hash_map::DefaultHasher::new();
            bytes.hash(&mut h);
            h.finish()
        };
        let b = prefix.as_bytes();
        Self {
            len: b.len(),
            head: hash(&b[..b.len().min(256)]),
            tail: hash(&b[b.len().saturating_sub(256)..]),
            width,
        }
    }
}

/// Byte length of the part of a streaming Markdown answer that is complete:
/// up to and including its last blank line outside a code fence. Blocks
/// before it render the same however much more text arrives.
fn stable_prefix_len(text: &str) -> usize {
    let mut in_fence = false;
    let mut stable = 0;
    let mut offset = 0;
    for line in text.split_inclusive('\n') {
        offset += line.len();
        let trimmed = line.trim();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            in_fence = !in_fence;
        } else if trimmed.is_empty() && !in_fence && line.ends_with('\n') {
            stable = offset;
        }
    }
    stable
}

/// A setup failure explained the way `doctor` explains it (#744).
fn wizard_explain(raw: &str, base_url: &str, model: &str) -> formless_protocol::ErrorExplained {
    let ctx = formless_core::errors::ErrorContext {
        base_url: base_url.trim(),
        model,
        alternatives: Vec::new(),
    };
    formless_core::errors::explain(raw, &ctx)
}

/// What `ContextUsage.context_source` means, for `/context`.
fn window_source_text(source: &str) -> &'static str {
    match source {
        "configured" => "from provider.model_context_tokens",
        "endpoint" => "reported by the endpoint's /models",
        _ => "provider.context_tokens (the endpoint didn't report this model's)",
    }
}

/// `s` on one line in at most `max` screen columns (the `…` included),
/// cut between clusters (#785).
fn truncate_chars(s: &str, max: usize) -> String {
    let flat: String = s.chars().map(|c| if c == '\n' { ' ' } else { c }).collect();
    text::truncate(&flat, max)
}

fn memory_activity_note(memory: &formless_protocol::MemoryInfo) -> String {
    let source = match memory.session_id.as_deref() {
        Some(session) => format!(
            "from session {}",
            plain::display_text(&truncate_chars(session, 8))
        ),
        None => plain::display_text(&memory.author),
    };
    format!(
        "memory {} [{}{}] {} · {source}",
        plain::display_text(&memory.id),
        plain::display_text(&memory.scope),
        if memory.enabled { "" } else { ", off" },
        plain::display_text(&memory.text),
    )
}

/// Borrow this Session's user payloads; collecting the iterator copies only
/// references. Rendering selects a single entry without collecting at all.
fn input_history<'a>(
    messages: &'a [MessageInfo],
    session: Option<&'a str>,
) -> impl DoubleEndedIterator<Item = &'a str> + 'a {
    messages
        .iter()
        .filter(move |message| {
            message.role == "user" && session == Some(message.session_id.as_str())
        })
        .map(|message| message.content.as_str())
}

/// Bound preview work before newline expansion/terminal measurement. Drop the
/// final partial cluster when the byte budget cuts a very large history entry.
fn history_preview(text: &str, columns: usize) -> String {
    let mut end = text.len().min(columns.saturating_mul(32).max(64));
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    if end < text.len() {
        end = text::prev_cluster(&text[..end], end);
    }
    let mut flat = text[..end].replace('\n', " ⏎ ");
    if end < text.len() {
        flat.push('…');
    }
    text::truncate(&flat, columns)
}

