    #[test]
    fn the_queue_follows_events_and_keeps_a_stale_draft_from_being_sent() {
        use formless_protocol::QueuedMessage;
        let mut app = test_app();
        let q = |id: i64, t: &str| QueuedMessage {
            id,
            content: t.into(),
            revision: Some(0),
        };
        app.on_event(Event::QueueChanged {
            session_id: "s1".into(),
            queued: vec![q(1, "first"), q(2, "second")],
        });
        assert_eq!(app.queued.len(), 2);
        app.queue_command("queue edit 2");
        assert_eq!(app.editing_queued.map(|edit| edit.id), Some(2));
        assert_eq!(app.input.expanded(), "second");
        // It is sent meanwhile. The previous draft cannot become a chat send.
        app.on_event(Event::QueueChanged {
            session_id: "s1".into(),
            queued: vec![q(1, "first")],
        });
        assert!(app.editing_queued.unwrap().stale);
        app.submit_chat(false);
        assert_eq!(app.input.expanded(), "second");
        // Another Session's queue is not shown here.
        app.on_event(Event::QueueChanged {
            session_id: "s2".into(),
            queued: vec![],
        });
        assert_eq!(app.queued.len(), 1);
    }

    #[test]
    fn queued_save_uses_opened_revision_and_preserves_a_rejected_draft() {
        let mut app = test_app();
        let (client, sent) = DaemonClient::recording();
        let (reply, inbox) = mpsc::channel();
        app.client = Some(client);
        app.inbox = Some(inbox);
        let item = QueuedMessage {
            id: 9,
            content: "original".into(),
            revision: Some(1),
        };
        app.on_event(Event::QueueChanged {
            session_id: "s1".into(),
            queued: vec![item.clone()],
        });
        app.queue_command("queue edit 1");
        app.input.set("edit from this client");
        app.submit_chat(false);
        let request: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
        assert!(
            matches!(request.request, Request::EditQueuedIfCurrent { id:9, revision:1, ref content, .. } if content == "edit from this client")
        );
        reply
            .send(ServerMessage::Response {
                id: request.id,
                ok: false,
                result: None,
                error: Some("queued message moved".into()),
            })
            .unwrap();
        app.drain_daemon();
        assert!(app.editing_queued.unwrap().stale);
        assert_eq!(app.input.expanded(), "edit from this client");
        assert!(app.notes.last().unwrap().contains("queued message moved"));
        app.submit_chat(false);
        assert!(sent.try_recv().is_err());

        app.on_event(Event::QueueChanged {
            session_id: "s1".into(),
            queued: vec![QueuedMessage {
                revision: Some(2),
                ..item
            }],
        });
        app.queue_command("queue edit 1");
        app.submit_chat(false);
        let request: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
        assert!(matches!(
            request.request,
            Request::EditQueuedIfCurrent {
                id: 9,
                revision: 2,
                ..
            }
        ));
        app.on_event(Event::QueueChanged {
            session_id: "s1".into(),
            queued: vec![],
        });
        reply
            .send(ServerMessage::Response {
                id: request.id,
                ok: true,
                result: Some(serde_json::json!({"ok":true})),
                error: None,
            })
            .unwrap();
        app.drain_daemon();
        assert!(app.editing_queued.is_none() && app.input.is_empty());
    }

    #[test]
    fn dropped_progress_refreshes_durable_usage_and_marks_transient_progress_unknown() {
        use formless_protocol::{DroppedEventKind as K, UsageInfo};
        let mut app = test_app();
        let (client, sent) = DaemonClient::recording();
        let (tx, inbox) = mpsc::channel();
        app.client = Some(client);
        app.inbox = Some(inbox);
        app.run_usage.insert("s1".into(), UsageInfo::default());
        app.on_event(Event::ToolCallStarted {
            invocation_id: None,
            session_id: "s1".into(),
            run_id: "r1".into(),
            tool_name: "import".into(),
            version: 1,
            arguments: "{}".into(),
            depth: 0,
        });
        app.live_tools[0].progress = Some((Some(0.9), "stale".into()));
        app.live_tools[0].stalled_secs = Some(60);
        let gap = || Event::DeltasDropped {
            session_id: "s1".into(),
            run_id: "r1".into(),
            kinds: vec![K::RunUsage, K::ToolProgress, K::InvocationActivity],
            handle: None,
            model: None,
        };
        app.on_event(gap());
        app.on_event(gap());
        assert!(!app.run_usage.contains_key("s1"));
        assert_eq!(
            app.live_tools[0].progress,
            Some((None, "progress updates skipped".into()))
        );
        assert_eq!(app.live_tools[0].stalled_secs, None);
        let requests: Vec<RequestEnvelope> = sent
            .try_iter()
            .map(|s| serde_json::from_str(&s).unwrap())
            .collect();
        assert_eq!(
            requests.len(),
            2,
            "duplicate warnings share in-flight refreshes"
        );
        for req in requests {
            let result = match req.request {
                Request::SessionUsage { session_id } => {
                    assert_eq!(session_id, "s1");
                    serde_json::json!({"last_run": UsageInfo { steps: 3, ..UsageInfo::default() }})
                }
                Request::ListInvocations => serde_json::json!([]),
                other => panic!("unexpected gap refresh: {other:?}"),
            };
            tx.send(ServerMessage::Response {
                id: req.id,
                ok: true,
                result: Some(result),
                error: None,
            })
            .unwrap();
        }
        app.drain_daemon();
        assert_eq!(app.run_usage["s1"].steps, 3);
        assert!(app
            .notes
            .iter()
            .any(|n| n.contains("progress is unavailable")));
        // An in-flight snapshot must never overwrite a newer streamed value.
        app.on_event(gap());
        let requests: Vec<RequestEnvelope> = sent
            .try_iter()
            .map(|s| serde_json::from_str(&s).unwrap())
            .collect();
        app.on_event(Event::RunUsage {
            session_id: "s1".into(),
            run_id: "r1".into(),
            usage: UsageInfo {
                steps: 9,
                ..UsageInfo::default()
            },
        });
        for req in requests {
            let result = if matches!(req.request, Request::SessionUsage { .. }) {
                serde_json::json!({"last_run": UsageInfo { steps: 4, ..UsageInfo::default() }})
            } else {
                serde_json::json!([])
            };
            tx.send(ServerMessage::Response {
                id: req.id,
                ok: true,
                result: Some(result),
                error: None,
            })
            .unwrap();
        }
        app.drain_daemon();
        assert_eq!(app.run_usage["s1"].steps, 9);
        app.pull_status = Some("stale 90%".into());
        app.on_event(Event::DeltasDropped {
            session_id: String::new(),
            run_id: String::new(),
            kinds: vec![K::ModelPullProgress],
            handle: None,
            model: Some("model".into()),
        });
        assert!(app.pull_status.is_none());
        assert!(app
            .notes
            .iter()
            .any(|n| n.contains("download progress unavailable for model")));
    }

