        let _: Vec<_> = sent.try_iter().collect();
        let (id, _) = app.reconnect_request.clone().unwrap();
        tx.send(ServerMessage::err_code(
            id,
            codes::NOT_FOUND,
            "session not found".into(),
        ))
        .unwrap();
