    #[test]
    fn reconnect_gap_reads_preserve_newer_live_usage_in_either_reply_order() {
        use formless_protocol::{DroppedEventKind as K, UsageInfo};
        for session_reply_first in [false, true] {
            let mut app = test_app();
            app.daemon_lost();
            let (client, sent) = DaemonClient::recording();
            let (tx, inbox) = mpsc::channel();
            app.attach_daemon(client, inbox);
            let _: Vec<_> = sent.try_iter().collect();
            let (snapshot, _) = app.reconnect_request.clone().unwrap();
            app.on_event(Event::DeltasDropped {
                session_id: "s1".into(),
                run_id: "r1".into(),
                kinds: vec![K::RunUsage, K::InvocationActivity],
                handle: None,
                model: None,
            });
            let reads: Vec<RequestEnvelope> = sent
                .try_iter()
                .map(|line| serde_json::from_str(&line).unwrap())
                .collect();
            assert_eq!(reads.len(), 2, "gap recovery remains available offline");
            app.on_event(Event::RunUsage {
                session_id: "s1".into(),
                run_id: "r1".into(),
                usage: UsageInfo {
                    steps: 9,
                    context_used: 200,
                    context_tokens: 2000,
                    ..UsageInfo::default()
                },
            });
            let session_reply = || ServerMessage::Response {
                id: snapshot,
                ok: true,
                result: Some(reconnect_snapshot(false, vec![])),
                error: None,
            };
            if session_reply_first {
                tx.send(session_reply()).unwrap();
            }
            for read in reads {
                let result = match read.request {
                    Request::SessionUsage { session_id } => {
                        assert_eq!(session_id, "s1");
                        serde_json::json!({"last_run": UsageInfo {
                            steps: 3,
                            context_used: 100,
                            context_tokens: 1000,
                            ..UsageInfo::default()
                        }})
                    }
                    Request::ListInvocations => serde_json::json!([]),
                    other => panic!("unexpected recovery action: {other:?}"),
                };
                tx.send(ServerMessage::Response {
                    id: read.id,
                    ok: true,
                    result: Some(result),
                    error: None,
                })
                .unwrap();
            }
            if !session_reply_first {
                tx.send(session_reply()).unwrap();
            }
            app.drain_daemon();
            assert!(app.offline.is_none());
            assert_eq!(app.run_usage["s1"].steps, 9);
            assert_eq!(app.context_fill["s1"], (200, 2000));
            assert!(sent.try_recv().is_err(), "recovery never replays commands");
        }
    }

    #[test]
    fn deletion_during_reconnect_stashes_the_old_draft_before_replacement_selection() {
        for replacement_has_draft in [false, true] {
            let mut app = test_app();
            app.input.set("private text from Session one");
            let old_files = vec![("private.bin".into(), vec![1, 2, 3])];
            app.attachments = old_files.clone();
            if replacement_has_draft {
                app.drafts.insert(
                    "s2".into(),
                    Draft {
                        input: "Session two's draft".into(),
                        attachments: vec![("two.bin".into(), vec![9])],
                    },
                );
            }
            app.daemon_lost();
            let (client, sent) = DaemonClient::recording();
            let (tx, inbox) = mpsc::channel();
            app.attach_daemon(client, inbox);
            let initial: Vec<RequestEnvelope> = sent
                .try_iter()
                .map(|line| serde_json::from_str(&line).unwrap())
                .collect();
            let old_list = initial
                .iter()
                .find(|request| matches!(request.request, Request::ListSessions))
                .unwrap()
                .id;
            let (old_snapshot, _) = app.reconnect_request.clone().unwrap();
            tx.send(ServerMessage::Event(Event::SessionDeleted {
                id: "s1".into(),
            }))
            .unwrap();
            // Both already queued replies are now stale, including a list
            // taken before deletion that still contains the old Session.
            tx.send(ServerMessage::Response {
                id: old_snapshot,
                ok: true,
                result: Some(reconnect_snapshot(false, vec![])),
                error: None,
            })
            .unwrap();
            tx.send(ServerMessage::Response {
                id: old_list,
                ok: true,
                result: Some(serde_json::json!([{
                    "id":"s1", "name":"stale", "created_at":"", "updated_at":""
                }])),
                error: None,
            })
            .unwrap();
            app.drain_daemon();
            assert!(app.current.is_none() && app.offline.is_some());
            assert!(app.input.is_empty() && app.attachments.is_empty());
            assert_eq!(
                app.drafts["s1"].input.expanded(),
                "private text from Session one"
            );
            assert_eq!(app.drafts["s1"].attachments, old_files);
            let fresh: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
            assert!(matches!(fresh.request, Request::ListSessions));
            tx.send(ServerMessage::Response {
                id: fresh.id,
                ok: true,
                result: Some(serde_json::json!([{
                    "id":"s2", "name":"replacement", "created_at":"", "updated_at":""
                }])),
                error: None,
            })
            .unwrap();
            app.drain_daemon();
            assert_eq!(app.current.as_deref(), Some("s2"));
            let (snapshot, session) = app.reconnect_request.clone().unwrap();
            assert_eq!(session, "s2");
            tx.send(ServerMessage::Response {
                id: snapshot,
                ok: true,
                result: Some(reconnect_snapshot(false, vec![])),
                error: None,
            })
            .unwrap();
            app.drain_daemon();
            assert!(app.offline.is_none());
            assert_eq!(
                app.input.expanded(),
                if replacement_has_draft {
                    "Session two's draft"
                } else {
                    ""
                }
            );
            assert_eq!(
                app.attachments,
                if replacement_has_draft {
                    vec![("two.bin".into(), vec![9])]
                } else {
                    vec![]
                }
            );
            assert_eq!(app.drafts["s1"].attachments, old_files);
            assert!(sent
                .try_iter()
                .map(|line| serde_json::from_str::<RequestEnvelope>(&line).unwrap())
                .all(|request| !matches!(request.request, Request::SendMessage { .. })));
        }
    }

    #[test]
    fn a_pause_during_reconnect_preserves_its_resume_banner_and_explanation() {
        for explained in [
            None,
            Some(ErrorExplained {
                category: "server".into(),
                message: "A readable pause explanation".into(),
                action: Some("Try again".into()),
                details: "raw provider failure".into(),
            }),
        ] {
            let mut app = test_app();
            app.sessions = serde_json::from_value(serde_json::json!([{
                "id": "s1",
                "name": "Reconnect pause",
                "created_at": "",
                "updated_at": ""
            }]))
            .unwrap();
            app.daemon_lost();
            let (client, _sent) = DaemonClient::recording();
            let (tx, inbox) = mpsc::channel();
            app.attach_daemon(client, inbox);
            let (id, _) = app.reconnect_request.clone().unwrap();
            let expected = explained
                .as_ref()
                .map_or("raw provider failure", |why| why.message.as_str())
                .to_string();
            tx.send(ServerMessage::Event(Event::RunPaused {
                session_id: "s1".into(),
                run_id: "r1".into(),
                error: "raw provider failure".into(),
                explained,
            }))
            .unwrap();
            tx.send(ServerMessage::Event(Event::RunFinished {
                session_id: "s1".into(),
                run_id: "r1".into(),
                status: "paused".into(),
            }))
            .unwrap();
            // The read began while the Run was active, before its pause.
            // SendMessage appends the user's message before starting a Run;
            // include that durable history instead of a welcome-screen fixture.
            let mut snapshot = reconnect_snapshot(true, vec![]);
            snapshot["messages"] = serde_json::json!([msg("user", "Please continue my task")]);
            tx.send(ServerMessage::Response {
                id,
                ok: true,
                result: Some(snapshot),
                error: None,
            })
            .unwrap();
            app.drain_daemon();
            assert!(app.offline.is_none() && !app.running());
            assert_eq!(app.run_banner, Some(("paused".into(), expected.clone())));
            assert_eq!(app.last_error.as_deref(), Some("raw provider failure"));
            let screen = render(&mut app, 120, 30);
            assert!(
                screen.contains("/resume") && screen.contains(&expected),
                "{screen}"
            );
        }
    }

    #[test]
    fn an_interrupted_attachment_stage_restores_files_and_text_without_sending() {
        for (switch_session, newer_input) in [(false, false), (true, true), (false, true)] {
            let mut app = test_app();
            let (client, sent) = DaemonClient::recording();
            let (tx, inbox) = mpsc::channel();
            app.client = Some(client);
            app.inbox = Some(inbox);
            let original_files = vec![
                ("one.bin".into(), vec![1, 2]),
                ("two.bin".into(), vec![3, 4]),
            ];
            app.attachments = original_files.clone();
            app.input.set("send these files");
            app.submit_chat(false);
            let requests: Vec<RequestEnvelope> = sent
                .try_iter()
                .map(|line| serde_json::from_str(&line).unwrap())
                .collect();
            assert_eq!(requests.len(), 2);
            assert!(requests
                .iter()
                .all(|request| matches!(request.request, Request::AttachFile { .. })));
            assert!(app.input.is_empty() && app.attachments.is_empty());
            assert!(
                app.sends.unsent("s1").is_none(),
                "SendMessage has not yet been issued"
            );
            if switch_session {
                app.switch_session("s2".into());
            }
            if newer_input {
                app.input.set("a newer draft");
                app.attachments = vec![("new.bin".into(), vec![9])];
            }
            // Only one attachment was acknowledged before the socket ended.
            tx.send(ServerMessage::Response {
                id: requests[0].id,
                ok: true,
                result: Some(serde_json::json!({"attached":true})),
                error: None,
            })
            .unwrap();
            drop(tx);
            app.drain_daemon();
            assert!(app.offline.is_some() && app.pending_send.is_none());
            if switch_session {
                assert_eq!(app.input.expanded(), "a newer draft");
                assert_eq!(app.attachments, vec![("new.bin".into(), vec![9])]);
                assert_eq!(app.drafts["s1"].input.expanded(), "send these files");
                assert_eq!(app.drafts["s1"].attachments, original_files);
            } else if newer_input {
                assert_eq!(app.input.expanded(), "a newer draft");
                assert_eq!(app.interrupted_attachment_sends.len(), 1);
                app.input.clear();
                app.drain_daemon(); // Restore for review, not as a send action.
                assert_eq!(app.input.expanded(), "send these files");
                assert!(app.attachments.starts_with(&original_files));
                assert_eq!(
                    app.attachments.last().unwrap(),
                    &("new.bin".into(), vec![9])
                );
                assert!(app.interrupted_attachment_sends.is_empty());
            } else {
                assert_eq!(app.input.expanded(), "send these files");
                assert_eq!(app.attachments, original_files);
            }
            assert!(sent
                .try_iter()
                .map(|line| serde_json::from_str::<RequestEnvelope>(&line).unwrap())
                .all(|request| !matches!(request.request, Request::SendMessage { .. })));
        }
    }

    #[test]
    fn an_attachment_timeout_restores_the_draft_online_and_ignores_late_replies() {
        for newer_input in [false, true] {
            let mut app = test_app();
            let (client, sent) = DaemonClient::recording();
            let (tx, inbox) = mpsc::channel();
            app.client = Some(client);
            app.inbox = Some(inbox);
            let files = vec![("one.bin".into(), vec![1]), ("two.bin".into(), vec![2])];
            app.input.set("keep this attachment draft");
            app.attachments = files.clone();
            app.submit_chat(false);
            let requests: Vec<RequestEnvelope> = sent
                .try_iter()
                .map(|line| serde_json::from_str(&line).unwrap())
                .collect();
            assert_eq!(requests.len(), 2);
            assert!(requests
                .iter()
                .all(|request| matches!(request.request, Request::AttachFile { .. })));
            if newer_input {
                app.input.set("newer text must survive");
            }
            // Only the first upload expires. The other is still in flight,
            // and the socket remains open throughout recovery.
            app.pending_since.insert(
                requests[0].id,
                Instant::now() - REQUEST_DEADLINE - Duration::from_secs(1),
            );
            app.drain_daemon();
            assert!(app.offline.is_none() && app.client.is_some() && app.inbox.is_some());
            assert!(app.pending_send.is_none());
            assert!(requests.iter().all(|request| {
                !app.pending.contains_key(&request.id)
                    && !app.pending_since.contains_key(&request.id)
            }));
            if newer_input {
                assert_eq!(app.input.expanded(), "newer text must survive");
                assert_eq!(app.interrupted_attachment_sends.len(), 1);
                app.input.clear();
                app.drain_daemon();
            }
            assert_eq!(app.input.expanded(), "keep this attachment draft");
            assert_eq!(app.attachments, files);
            assert!(app.interrupted_attachment_sends.is_empty());
            assert!(sent.try_recv().is_err(), "timeout does not send the draft");

            // Start a fresh upload, then deliver both old replies. Neither
            // acknowledgement may complete this new stage or send a message.
            app.input.set("a fresh attachment draft");
            app.attachments = vec![("fresh.bin".into(), vec![3])];
            app.submit_chat(false);
            let fresh: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
            assert!(matches!(fresh.request, Request::AttachFile { .. }));
            for request in requests {
                tx.send(ServerMessage::Response {
                    id: request.id,
                    ok: true,
                    result: Some(serde_json::json!({"attached":true})),
                    error: None,
                })
                .unwrap();
            }
            app.drain_daemon();
            assert!(app.offline.is_none());
            assert_eq!(app.pending_send.as_ref().unwrap().waiting, 1);
            assert!(app.pending.contains_key(&fresh.id));
            assert!(
                sent.try_recv().is_err(),
                "late replies never send a message"
            );
        }
    }

    #[test]
    fn failed_or_incomplete_reconnect_reads_keep_the_banner_and_retry_reads_only() {
        let mut app = test_app();
        app.daemon_lost();
        let (client, sent) = DaemonClient::recording();
        let (tx, inbox) = mpsc::channel();
        app.attach_daemon(client, inbox);
        let _: Vec<_> = sent.try_iter().collect();
        let (id, _) = app.reconnect_request.clone().unwrap();
        tx.send(ServerMessage::Response {
            id,
            ok: false,
            result: None,
            error: Some("read failed".into()),
        })
        .unwrap();
        app.drain_daemon();
        assert!(app.offline.is_some() && app.reconnect_request.is_none());
        let (since, _) = app.offline.unwrap();
        app.offline = Some((since, Instant::now() - Duration::from_secs(3)));
        app.try_reconnect();
        let retried: Vec<RequestEnvelope> = sent
            .try_iter()
            .map(|line| serde_json::from_str(&line).unwrap())
            .collect();
        assert_eq!(retried.len(), 2);
        assert!(retried.iter().all(|request| matches!(
            request.request,
            Request::Subscribe { .. } | Request::GetSession { .. }
        )));
        let (next, _) = app.reconnect_request.clone().unwrap();
        assert_ne!(next, id);
        tx.send(ServerMessage::Response {
            id: next,
            ok: true,
            result: Some(serde_json::json!({})),
            error: None,
        })
        .unwrap();
        app.drain_daemon();
        assert!(app.offline.is_some() && app.reconnect_request.is_none());
        app.begin_reconnect_snapshot();
        let (next, _) = app.reconnect_request.clone().unwrap();
        app.pending_since.insert(
            next,
            Instant::now() - REQUEST_DEADLINE - Duration::from_secs(1),
        );
        app.drain_daemon();
        assert!(app.offline.is_some() && app.reconnect_request.is_none());
    }

    #[test]
    fn buffered_send_acknowledgement_before_eof_does_not_restore_an_accepted_send() {
        let mut app = test_app();
        let (client, sent) = DaemonClient::recording();
        let (tx, inbox) = mpsc::channel();
        app.client = Some(client);
        app.inbox = Some(inbox);
        app.input.set("accepted once");
        app.submit_chat(false);
        let first: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
        let first_key = serde_json::to_value(&first.request).unwrap()["client_msg_id"].clone();
        tx.send(ServerMessage::Response {
            id: first.id,
            ok: true,
            result: Some(serde_json::json!({"started": true})),
            error: None,
        })
        .unwrap();
        drop(tx); // The reader delivered the acknowledgement, then saw EOF.
        app.drain_daemon();
        assert!(app.offline.is_some() && app.inbox.is_none());
        assert_eq!(app.input.expanded(), "");
        assert_eq!(app.sends.unsent(app.current.as_deref().unwrap()), None);
        assert!(app.pending.is_empty());

        // A later deliberate send of identical text is a new action.
        let (client, sent) = DaemonClient::recording();
        app.client = Some(client);
        app.offline = None;
        app.input.set("accepted once");
        app.submit_chat(false);
        let next: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
        assert_ne!(
            serde_json::to_value(&next.request).unwrap()["client_msg_id"],
            first_key
        );
    }

    #[test]
    fn eof_without_a_send_acknowledgement_restores_only_an_empty_draft() {
        for newer_draft in [None, Some("new draft")] {
            let mut app = test_app();
            let (client, sent) = DaemonClient::recording();
            let (tx, inbox) = mpsc::channel::<ServerMessage>();
            app.client = Some(client);
            app.inbox = Some(inbox);
            app.input.set("unacknowledged send");
            app.submit_chat(false);
            let _: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
            if let Some(text) = newer_draft {
                app.input.set(text);
            }
            drop(tx);
            app.drain_daemon();
            assert!(app.offline.is_some() && app.inbox.is_none());
            assert_eq!(
                app.input.expanded(),
                newer_draft.unwrap_or("unacknowledged send")
            );
            assert_eq!(
                app.sends.unsent(app.current.as_deref().unwrap()),
                Some("unacknowledged send")
            );
        }
    }

    #[test]
    fn late_send_acknowledgement_retracts_only_the_restored_retry_draft() {
        for newer_draft in [None, Some("new draft")] {
            let mut app = test_app();
            let (client, sent) = DaemonClient::recording();
            let (tx, inbox) = mpsc::channel();
            app.client = Some(client);
            app.inbox = Some(inbox);
            app.input.set("send once");
            app.submit_chat(false);
            let sent: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
            app.pending_since.insert(
                sent.id,
                Instant::now() - REQUEST_DEADLINE - Duration::from_secs(1),
            );
            app.expire_pending();
            if let Some(text) = newer_draft {
                app.input.set(text);
            }
            tx.send(ServerMessage::Response {
                id: sent.id,
                ok: true,
                result: Some(serde_json::json!({"started": true})),
                error: None,
            })
            .unwrap();
            app.drain_daemon();
            assert_eq!(app.input.expanded(), newer_draft.unwrap_or(""));
        }
    }

    #[tokio::test]
    async fn timed_out_tui_send_reuses_its_key_and_appends_one_user_message() {
        let _env = credential_env::EnvGuard::isolated();
        let mut app = test_app();
        let mut cfg = Config::default();
        cfg.provider.base_url = "http://127.0.0.1:9".into();
        cfg.provider.model = "test".into();
        cfg.provider.max_retries = 0;
        cfg.naming.enabled = false;
        cfg.skills.auto_create = false;
        cfg.save(&app.paths).unwrap();
        let store = formless_core::Store::open(&app.paths.db_file()).unwrap();
        let session = store.create_session(None).unwrap();
        app.current = Some(session.id.clone());
        let daemon =
            std::sync::Arc::new(formless_core::daemon::Daemon::new(app.paths.clone()).unwrap());
        let (client, sent) = DaemonClient::recording();
        let (tx, inbox) = mpsc::channel();
        app.client = Some(client);
        app.inbox = Some(inbox);
        app.input.set("send once");
        app.submit_chat(false);
        let first: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
        let original = serde_json::to_value(&first.request).unwrap();
        daemon.handle(first.request).await.unwrap();
        // The daemon executed it but its acknowledgement was lost.
        app.pending_since.insert(
            first.id,
            Instant::now() - REQUEST_DEADLINE - Duration::from_secs(1),
        );
        app.expire_pending();
        assert_eq!(app.input.expanded(), "send once");
        app.submit_chat(false);
        let retry: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
        assert_eq!(serde_json::to_value(&retry.request).unwrap(), original);
        let outcome = daemon.handle(retry.request).await.unwrap();
        assert_eq!(
            store
                .list_messages(&session.id)
                .unwrap()
                .iter()
                .filter(|m| m.role == "user" && m.content == "send once")
                .count(),
            1
        );
        tx.send(ServerMessage::Response {
            id: retry.id,
            ok: true,
            result: Some(outcome),
            error: None,
        })
        .unwrap();
        app.drain_daemon();
        app.input.set("send once");
        app.submit_chat(false);
        let fresh: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
        assert_ne!(
            serde_json::to_value(fresh.request).unwrap()["client_msg_id"],
            original["client_msg_id"]
        );
        // The send response can precede the detached Run's cleanup. Do not
        // restore inherited credentials while that task still reads config.
        tokio::time::timeout(Duration::from_secs(10), async {
            while std::sync::Arc::strong_count(&daemon) != 1 {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("send retry Run did not finish within 10 seconds");
        drop(daemon);
    }

    #[test]
    fn attaching_each_replacement_daemon_refreshes_its_approvals_mode() {
        let mut app = test_app();
        let cfg = Config::default();
        cfg.save(&app.paths).unwrap();
        for secure in [true, false] {
            app.daemon_lost();
            assert_eq!(app.daemon_secure, None);
            let (client, sent) = DaemonClient::recording();
            let (tx, inbox) = mpsc::channel();
            app.attach_daemon(client, inbox);
            let status: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
            assert!(matches!(status.request, Request::Status));
            assert_eq!(app.daemon_secure, None, "unknown until this daemon replies");
            tx.send(ServerMessage::Response {
                id: status.id,
                ok: true,
                result: Some(serde_json::json!({"secure": secure})),
                error: None,
            })
            .unwrap();
            app.drain_daemon();
            assert_eq!(app.daemon_secure, Some(secure));
            let row = app
                .settings_rows()
                .into_iter()
                .find(|r| r.key == "security.secure")
                .unwrap();
            assert_eq!(
                row.value,
                settings::approvals_text(secure, cfg.security.secure)
            );
        }
        app.daemon_lost();
        assert_eq!(app.daemon_secure, None);
        assert_eq!(
            app.settings_rows()
                .into_iter()
                .find(|r| r.key == "security.secure")
                .unwrap()
                .value,
            "daemon mode unknown"
        );
    }

    #[test]
    fn manual_skill_load_reports_only_confirmed_success() {
        let mut app = test_app();
        let (client, sent) = DaemonClient::recording();
        let (reply, inbox) = std::sync::mpsc::channel();
        app.client = Some(client);
        app.inbox = Some(inbox);
        for ok in [false, true] {
            app.notes.clear();
            app.slash("skill:foo");
            assert!(app.notes.is_empty());
            let request: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
            reply
                .send(ServerMessage::Response {
                    id: request.id,
                    ok,
                    result: ok.then(|| serde_json::json!({"loaded":"foo"})),
                    error: (!ok).then(|| "skill 'foo' is retired".into()),
                })
                .unwrap();
            app.drain_daemon();
            assert_eq!(
                app.notes.last().map(String::as_str),
                Some(if ok {
                    "loaded skill foo"
                } else {
                    "daemon: skill 'foo' is retired"
                })
            );
        }
    }

    #[test]
    fn skill_command_prefixes_dispatch_to_their_distinct_requests() {
        let mut app = test_app();
        let (client, sent) = DaemonClient::recording();
        app.client = Some(client);
        for (command, expected) in [
            ("skills", Request::ListSkills),
            ("skills foo", Request::GetSkill { name: "foo".into() }),
            (
                "skills enable foo",
                Request::SetSkillEnabled {
                    name: "foo".into(),
                    enabled: true,
                },
            ),
            (
                "skills disable foo",
                Request::SetSkillEnabled {
                    name: "foo".into(),
                    enabled: false,
                },
            ),
            (
                "skill:foo",
                Request::LoadSkill {
                    session_id: "s1".into(),
                    name: "foo".into(),
                    args: None,
                },
            ),
            (
                "skill:foo do this",
                Request::LoadSkill {
                    session_id: "s1".into(),
                    name: "foo".into(),
                    args: Some("do this".into()),
                },
            ),
        ] {
            app.slash(command);
            let envelope: RequestEnvelope =
                serde_json::from_str(&sent.try_recv().expect(command)).unwrap();
            assert_eq!(
                serde_json::to_value(envelope.request).unwrap(),
                serde_json::to_value(expected).unwrap(),
                "{command}"
            );
            assert!(sent.try_recv().is_err(), "{command} must send one request");
        }
    }

    #[test]
    fn compare_answers_sit_side_by_side_or_stack_when_narrow() {
        use formless_protocol::ComparisonResult;
        let r = |m: &str, a: &str| ComparisonResult {
            model: m.into(),
            session_id: format!("s-{m}"),
            status: "completed".into(),
            answer: a.into(),
            duration_ms: 1500,
            tokens: 42,
            cost: Some(0.0012),
            steps: 1,
        };
        let results = vec![r("alpha", "short"), r("beta", "a longer answer here")];
        let wide = compare_lines(&results, 100);
        assert!(wide[0].contains("alpha · completed · 1.5s · 42 tokens · 1 steps · $0.0012"));
        assert!(
            wide.iter()
                .any(|l| l.contains("short") && l.contains("│ a longer answer here")),
            "{wide:?}"
        );
        let narrow = compare_lines(&results, 40);
        assert!(narrow.iter().any(|l| l == "── beta ──"));
        assert!(!narrow.iter().any(|l| l.contains('│')));
    }

