    #[test]
    fn a_long_mcp_input_never_hides_the_approval_keys() {
        let payload = format!(
            "input: {{\"code_to_execute\": \"{}\"}}",
            "import os\\nprint(os.listdir('.'))\\n".repeat(60)
        );
        let detail = format!(
            "MCP tool COMPOSIO_REMOTE_WORKBENCH on server composio\n⚠ may be destructive\n{payload}\n{}",
            "more\n".repeat(30)
        );
        let req = ApprovalReq {
            context: None,
            approval_id: "a".into(),
            tool_name: "mcp__composio__COMPOSIO_REMOTE_WORKBENCH".into(),
            version: 0,
            capabilities: vec!["mcp:composio".into()],
            memory_mb: 0,
            detail: Some(detail),
            already_allowed: Vec::new(),
            code_preview: Some("line\n".repeat(20)),
            tool_id: None,
            session_id: None,
        };
        for h in [40, 20] {
            let mut app = test_app();
            app.approvals.push_back(req.clone());
            let screen = render(&mut app, 100, h);
            assert!(
                screen.contains("always") && screen.contains("once") && screen.contains("deny"),
                "{h} rows: {screen}"
            );
            assert!(screen.contains("v full code"), "{h} rows: {screen}");
            assert!(screen.contains("i full approval"), "{h} rows: {screen}");
            let (client, sent) = DaemonClient::recording();
            app.client = Some(client);
            app.input_focus = false;
            app.key(key(KeyCode::Char('i')));
            let inspector = app
                .pager
                .as_ref()
                .expect("full approval inspector stays reachable on a short terminal");
            let full = inspector.lines.join("\n");
            assert!(
                full.contains(req.detail.as_deref().unwrap()),
                "all MCP input/detail must remain inspectable at {h} rows"
            );
            assert!(
                full.contains(req.code_preview.as_deref().unwrap()),
                "the complete held code preview must remain inspectable"
            );
            assert!(
                full.contains("MCP tool COMPOSIO_REMOTE_WORKBENCH")
                    && full.contains("mcp:composio")
            );
            assert!(
                sent.try_recv().is_err(),
                "reading full approval evidence must not approve or execute anything"
            );
            app.key(key(KeyCode::Esc));
            app.key(key(KeyCode::Char('v')));
            assert!(
                app.pager
                    .as_ref()
                    .unwrap()
                    .lines
                    .join("\n")
                    .contains(&payload),
                "the existing MCP v detail view remains accessible"
            );
            assert!(sent.try_recv().is_err());
        }
    }

