    #[test]
    fn input_edits_recalls_history_and_keeps_pastes_whole() {
        let key = |code| KeyEvent::new(code, KeyModifiers::NONE);
        let with = |code, m| KeyEvent::new(code, m);
        let mut app = test_app();
        app.messages = ["first ask", "second ask"]
            .iter()
            .enumerate()
            .map(|(i, c)| MessageInfo {
                generated_by: None,
                id: format!("m{i}"),
                session_id: "s1".into(),
                seq: i as i64,
                role: "user".into(),
                content: c.to_string(),
                created_at: String::new(),
                meta: None,
            })
            .collect();
        for c in "helo".chars() {
            app.key(key(KeyCode::Char(c)));
        }
        app.key(key(KeyCode::Left));
        app.key(key(KeyCode::Char('l')));
        assert_eq!(app.input, "hello");
        // Up recalls this Session's messages; Down returns to the draft.
        app.key(key(KeyCode::Up));
        assert_eq!(app.input, "second ask");
        app.key(key(KeyCode::Up));
        assert_eq!(app.input, "first ask");
        app.key(key(KeyCode::Down));
        app.key(key(KeyCode::Down));
        assert_eq!(app.input, "hello");
        // Shift+Enter and a trailing backslash add newlines.
        app.key(with(KeyCode::Enter, KeyModifiers::SHIFT));
        app.key(key(KeyCode::Char('x')));
        app.key(key(KeyCode::Char('\\')));
        app.key(key(KeyCode::Enter));
        app.key(key(KeyCode::Char('y')));
        assert_eq!(app.input, "hello\nx\ny");
        // Up on a later line moves within the input, not through history.
        app.key(key(KeyCode::Up));
        assert_eq!(app.input, "hello\nx\ny");
        for (w, h) in [(1, 1), (12, 6), (80, 24)] {
            render(&mut app, w, h);
        }
        // Ctrl+U clears the cursor's line (now "x"); Ctrl+R finds an
        // earlier message.
        app.key(with(KeyCode::Char('u'), KeyModifiers::CONTROL));
        assert_eq!(app.input, "hello\n\ny");
        app.input.clear();
        app.key(with(KeyCode::Char('r'), KeyModifiers::CONTROL));
        for c in "first".chars() {
            app.key(key(KeyCode::Char(c)));
        }
        assert!(render(&mut app, 80, 24).contains("(history search) first"));
        app.key(key(KeyCode::Enter));
        assert_eq!(app.input, "first ask");
        // A big paste stays one block and is sent in full.
        app.input.clear();
        let big = vec!["row"; 30].join("\n");
        app.paste(&big);
        assert_eq!(app.input, "[pasted 30 lines #1]");
        assert_eq!(app.input.take(), big);
    }

    #[test]
    fn composer_arrows_follow_drawn_wrap_rows_before_history_and_extend_selection() {
        let mut app = test_app();
        app.messages.push(msg("user", "previous"));
        render(&mut app, 30, 20);
        let width = app.composer_text_width.get();
        let draft = "x".repeat(width * 2 + 3);
        app.input.set(&draft);
        render(&mut app, 30, 20);
        assert_eq!(app.input.layout(width).1, (2, 3));
        app.key(key(KeyCode::Up));
        assert_eq!(app.input.layout(width).1, (1, 3));
        assert_eq!(&*app.input, draft);
        app.key(KeyEvent::new(KeyCode::Up, KeyModifiers::SHIFT));
        assert_eq!(app.input.layout(width).1, (0, 3));
        assert_eq!(app.input.selected_text().unwrap().len(), width);
        app.input.set_modal_cursor(0);
        app.key(key(KeyCode::Up));
        assert_eq!(&*app.input, "previous");
        app.key(key(KeyCode::Down));
        assert_eq!(&*app.input, draft);
        render(&mut app, 45, 20);
        let resized = app.composer_text_width.get();
        assert_ne!(resized, width);
        app.key(key(KeyCode::Up));
        assert_eq!(&*app.input, draft);

        app.vim_mode = true;
        app.input.set("abcdefghijklmnop");
        app.composer_text_width.set(5);
        let cursor = app.input.cursor_byte();
        app.key(key(KeyCode::Up));
        assert_eq!(
            app.input.cursor_byte(),
            cursor,
            "Vim Insert retains its logical-line arrow behavior"
        );
    }

