    #[test]
    fn settings_editors_place_the_hardware_cursor_in_the_focused_field() {
        use ratatui::backend::{Backend, TestBackend};
        let mut app = test_app();
        Config::default().save(&app.paths).unwrap();
        app.view = View::Settings;
        let setting = "provider.stall_notice_secs";
        app.settings_sel = app
            .settings_rows()
            .iter()
            .position(|row| row.key == setting)
            .unwrap();
        app.settings_edit = Some((setting.into(), input::InputLine::from("abc")));
        app.key(key(KeyCode::Left));
        app.key(key(KeyCode::Left));
        let mut terminal = Terminal::new(TestBackend::new(80, 25)).unwrap();
        terminal.draw(|frame| draw(frame, &mut app)).unwrap();
        let caret = terminal.backend_mut().get_cursor_position().unwrap();
        assert_eq!(
            terminal.backend().buffer()[(caret.x - 1, caret.y)].symbol(),
            "a"
        );
        assert_eq!(
            terminal.backend().buffer()[(caret.x, caret.y)].symbol(),
            "b"
        );
        app.key(key(KeyCode::Char('X')));
        terminal.draw(|frame| draw(frame, &mut app)).unwrap();
        terminal
            .backend_mut()
            .assert_cursor_position((caret.x + 1, caret.y));
        assert_eq!(
            terminal.backend().buffer()[(caret.x, caret.y)].symbol(),
            "X"
        );

        app.slash("mcp add postgres");
        let form = app.settings_form.as_mut().unwrap();
        form.idx = 1;
        form.fields[1].input = input::InputLine::from("界e\u{301}S");
        app.key(key(KeyCode::Left));
        app.key(key(KeyCode::Left));
        terminal.draw(|frame| draw(frame, &mut app)).unwrap();
        let masked = terminal.backend_mut().get_cursor_position().unwrap();
        let buffer = terminal.backend().buffer();
        assert_eq!(buffer[(masked.x - 1, masked.y)].symbol(), "•");
        assert_eq!(buffer[(masked.x, masked.y)].symbol(), "•");
        assert_eq!(buffer[(masked.x + 1, masked.y)].symbol(), "•");
        assert_ne!(buffer[(masked.x + 2, masked.y)].symbol(), "•");
        assert!(!render(&mut app, 80, 25).contains("界e\u{301}S"));

        app.paste(&"a".repeat(30));
        let mut narrow = Terminal::new(TestBackend::new(16, 9)).unwrap();
        narrow.draw(|frame| draw(frame, &mut app)).unwrap();
        let scrolled = narrow.backend_mut().get_cursor_position().unwrap();
        assert!(scrolled.x > 0 && scrolled.x < 15 && scrolled.y > 0 && scrolled.y < 8);
        app.pager = Some(Pager {
            title: "Topmost pager".into(),
            lines: vec!["visible".into()],
            top: 0,
            left: 0,
            viewport: Default::default(),
            styled: Vec::new(),
        });
        narrow.backend_mut().set_cursor_position((0, 0)).unwrap();
        narrow.draw(|frame| draw(frame, &mut app)).unwrap();
        narrow.backend_mut().assert_cursor_position((0, 0));
        app.pager = None;
        for size in [1, 2, 3] {
            let mut tiny = Terminal::new(TestBackend::new(size, size)).unwrap();
            tiny.draw(|frame| draw_settings(frame, frame.area(), &app))
                .unwrap();
            let pos = tiny.backend_mut().get_cursor_position().unwrap();
            assert!(pos.x < size && pos.y < size);
        }
    }

    #[test]
    fn settings_selected_help_wraps_and_file_pointers_cannot_save() {
        let mut app = test_app();
        let mut cfg = Config::default();
        cfg.provider.stall_notice_secs = 121;
        cfg.save(&app.paths).unwrap();
        app.view = View::Settings;
        let rows = app.settings_rows();
        app.settings_sel = rows
            .iter()
            .position(|r| r.key == "provider.stall_notice_secs")
            .unwrap();
        for (width, height) in [(80, 24), (48, 24)] {
            let mut term =
                Terminal::new(ratatui::backend::TestBackend::new(width, height)).unwrap();
            term.draw(|f| draw_settings(f, f.area(), &app)).unwrap();
            let buffer = term.backend().buffer();
            let screen: String = (0..height)
                .map(|y| {
                    (0..width)
                        .map(|x| buffer[(x, y)].symbol())
                        .collect::<String>()
                })
                .collect();
            let joined: String = screen.split_whitespace().collect();
            assert!(joined.contains("default120"), "{screen}");
            assert!(joined.contains("changedfromdefault"), "{screen}");
            assert!(joined.contains("seconds"), "units are visible: {screen}");
        }
        // Even a long SPEC entry is fully readable in the existing scrollable
        // pager, and closing it returns to the same Settings selection.
        app.settings_sel = rows.iter().position(|r| r.key == "tui.theme").unwrap();
        let selected = app.settings_sel;
        app.settings_key(KeyEvent::new(KeyCode::Char('?'), KeyModifiers::NONE));
        let pager = app.pager.as_ref().unwrap();
        let all: String = pager
            .lines
            .iter()
            .flat_map(|line| line.split_whitespace())
            .collect();
        assert!(all.contains("defaultauto"));
        assert!(all.contains("Configuredvalue:matchesdefault"));
        assert!(all.contains("Everytextcolour"));
        app.key(KeyEvent::new(KeyCode::End, KeyModifiers::NONE));
        render(&mut app, 80, 10);
        assert_eq!(
            app.pager.as_ref().unwrap().top,
            app.pager.as_ref().unwrap().lines.len().saturating_sub(8)
        );
        app.key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
        assert!(app.pager.is_none());
        assert_eq!(app.view, View::Settings);
        assert_eq!(app.settings_sel, selected);
        let (client, sent) = DaemonClient::recording();
        app.client = Some(client);
        for key in [
            "provider.prices",
            "provider.routing_models",
            "hooks",
            "security",
            "optimiser.cooldown_secs",
        ] {
            app.settings_sel = rows.iter().position(|r| r.key == key).unwrap();
            app.settings_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
            assert!(app.settings_edit.is_none());
            assert!(app.settings_form.is_none());
            assert!(app.notes.last().unwrap().contains("edit config.toml"));
        }
        assert!(
            matches!(sent.try_recv(), Err(std::sync::mpsc::TryRecvError::Empty)),
            "read-only pointers issue no requests"
        );
        for (width, height) in [(1, 1), (20, 5), (80, 24)] {
            render(&mut app, width, height);
        }
    }

