    #[test]
    fn open_links_from_the_last_answer() {
        let mut app = test_app();
        app.messages = vec![MessageInfo {
            generated_by: None,
            id: "a".into(),
            session_id: "s".into(),
            seq: 1,
            role: "assistant".into(),
            content: "See [the docs](https://docs.rs/x) and https://example.com/page.".into(),
            created_at: String::new(),
            meta: None,
        }];
        app.slash("open link");
        assert_eq!(app.notes.last().unwrap(), "opening https://docs.rs/x");
        app.slash("open link 2");
        assert_eq!(
            app.notes.last().unwrap(),
            "opening https://example.com/page"
        );
        app.slash("open link 3");
        assert_eq!(app.notes.last().unwrap(), "the last answer has 2 link(s)");
        // The chat area is recorded for the OSC 8 pass.
        render(&mut app, 80, 20);
        assert!(app.chat_area.is_some());
    }

    #[test]
    fn chat_paints_exact_markdown_destinations_and_keeps_bare_url_trimming() {
        let mut app = test_app();
        let report = "https://example.com/report.";
        let balanced = "https://example.com/thing_(x)!";
        let bare = "https://example.com/bare";
        app.messages = vec![msg(
            "assistant",
            &format!("See [report]({report}), [{balanced}]({balanced}) and {bare}."),
        )];
        let text_for = |buffer: &ratatui::buffer::Buffer, link: &links::Painted| -> String {
            (link.x0..=link.x1)
                .map(|x| buffer[(x, link.y)].symbol())
                .collect()
        };
        let mut term = Terminal::new(ratatui::backend::TestBackend::new(120, 24)).unwrap();
        term.draw(|f| draw(f, &mut app)).unwrap();
        let buffer = term.backend().buffer();
        let found = links::scan_with_layout_links(
            buffer,
            app.chat_area.unwrap(),
            &app.chat_markdown_links,
            &mut |_| None,
        );
        for target in [report, balanced, bare] {
            let matches: Vec<_> = found.iter().filter(|link| link.url == target).collect();
            assert_eq!(matches.len(), 1, "{found:?}");
            assert_eq!(text_for(buffer, matches[0]), target);
        }
        let link = found.iter().find(|link| link.url == report).unwrap();
        assert_eq!(buffer[(link.x0 - 1, link.y)].symbol(), "(");
        assert_eq!(buffer[(link.x1 + 1, link.y)].symbol(), ")");
    }

    #[test]
    fn scrolled_markdown_destination_fragments_keep_the_full_target() {
        let mut app = test_app();
        let url = format!("https://example.com/{}.?", "abc".repeat(38));
        app.messages = vec![msg("assistant", &format!("Before. [destination]({url})"))];
        let mut term = Terminal::new(ratatui::backend::TestBackend::new(28, 9)).unwrap();
        term.draw(|f| draw(f, &mut app)).unwrap();
        let buffer = term.backend().buffer();
        let found = links::scan_with_layout_links(
            buffer,
            app.chat_area.unwrap(),
            &app.chat_markdown_links,
            &mut |_| None,
        );
        assert!(found.len() >= 2, "{found:?}");
        assert!(found.iter().all(|link| link.url == url), "{found:?}");
        assert!(found
            .iter()
            .all(|link| (link.x0..=link.x1)
                .all(|x| !matches!(buffer[(x, link.y)].symbol(), "(" | ")"))));
        assert!(app.chat_line_count > app.chat_view_height);
    }

    #[test]
    fn file_paths_in_the_chat_link_and_open() {
        // Tests run in the crate directory.
        assert!(resolve_path("src/lib.rs").is_some());
        assert!(resolve_path("src/nope.rs").is_none());
        let mut app = test_app();
        app.slash("open path Cargo.toml:3");
        let note = app.notes.last().unwrap();
        assert!(note.contains("Cargo.toml at line 3"), "{note}");
        app.slash("open path missing.rs");
        assert_eq!(app.notes.last().unwrap(), "no file missing.rs");
        // The OSC 8 pass links existing paths to file://.
        let area = Rect::new(0, 0, 50, 1);
        let mut buf = ratatui::buffer::Buffer::empty(area);
        buf.set_string(0, 0, "see src/lib.rs:10 and src/nope.rs", Style::default());
        let found = links::scan(&buf, area, &mut |p| {
            resolve_path(p).and_then(|f| links::file_url(&f))
        });
        assert_eq!(found.len(), 1);
        assert!(found[0].url.starts_with("file://") && found[0].url.ends_with("src/lib.rs"));
        assert_eq!(
            url::Url::parse(&found[0].url)
                .unwrap()
                .to_file_path()
                .unwrap()
                .canonicalize()
                .unwrap(),
            resolve_path("src/lib.rs").unwrap(),
            "terminal hyperlink must round-trip to the actual native file"
        );
        assert_eq!((found[0].x0, found[0].x1), (4, 16));
        let file = std::path::Path::new("file with spaces.rs");
        let code = external_editor::EditorCommand::parse("/usr/local/bin/code")
            .unwrap()
            .command(file, Some(4), false)
            .unwrap();
        let vim = external_editor::EditorCommand::parse("vim")
            .unwrap()
            .command(file, Some(4), false)
            .unwrap();
        assert!(code.get_args().any(|arg| arg == "-g") && !vim.get_args().any(|arg| arg == "-g"));
    }

    #[test]
    fn theme_follows_settings() {
        let mut app = test_app();
        std::fs::create_dir_all(&app.paths.config_dir).unwrap();
        let mut cfg = Config::default();
        cfg.tui.theme = "light".into();
        cfg.tui.colors.insert("user".into(), "#ff0000".into());
        cfg.tui.timestamps = !app.show_timestamps;
        cfg.tui.multi_pane = !app.multi_pane;
        cfg.save(&app.paths).unwrap();
        let (ts, mp) = (cfg.tui.timestamps, cfg.tui.multi_pane);
        app.on_event(Event::SettingsChanged);
        // Changed from another client (the web): applied live.
        assert_eq!((app.show_timestamps, app.multi_pane), (ts, mp));
        assert_eq!(fg(true, Color::Yellow).fg, Some(Color::Rgb(150, 100, 0)));
        assert_eq!(role_style(true, "user").fg, Some(Color::Rgb(255, 0, 0)));
        assert_eq!(fg(false, Color::Yellow).fg, None, "NO_COLOR still wins");
        theme::reset();
    }

    #[test]
    fn parsed_code_blocks_preserve_pager_ordinals_and_latest_answer() {
        let mut app = test_app();
        let message = |id: &str, role: &str, content: &str| MessageInfo {
            generated_by: None,
            id: id.into(),
            session_id: "s".into(),
            seq: 1,
            role: role.into(),
            content: content.into(),
            created_at: String::new(),
            meta: None,
        };
        app.messages = vec![message("old", "assistant", "```\nold\n```"), message("new", "assistant", "~~~\nfirst\n~~~\n\n    second\n\n```mermaid\ngraph LR\nA --> B\n```\n\n````\nlast\n```\ncontinued"), message("blank", "assistant", " "), message("user", "user", "ignored")];
        app.open_code("");
        assert_eq!(app.pager.as_ref().unwrap().title, "code block 4 of 4");
        assert_eq!(
            app.pager.as_ref().unwrap().lines,
            ["1 │ last", "2 │ ```", "3 │ continued"]
        );
        app.open_code("2");
        assert_eq!(app.pager.as_ref().unwrap().lines, ["1 │ second"]);
        app.open_code("3");
        assert_eq!(app.pager.as_ref().unwrap().title, "code block 3 of 4");
        assert!(app
            .pager
            .as_ref()
            .unwrap()
            .lines
            .iter()
            .any(|line| line.contains("graph LR")));
        for index in ["0", "5"] {
            app.open_code(index);
            assert!(app.notes.last().unwrap().contains("4 code block(s)"));
            app.copy_cmd(&format!("code {index}"));
            assert!(app.notes.last().unwrap().contains("4 code block(s)"));
        }
        app.messages[1].content = "No code in the newest answer".into();
        app.open_code("");
        assert!(app.notes.last().unwrap().contains("0 code block(s)"));
    }

