    fn side_pane_regions(app: &mut App, width: u16, height: u16) -> (Vec<String>, Vec<String>) {
        app.pane_widths = (25, 25);
        let mut terminal =
            Terminal::new(ratatui::backend::TestBackend::new(width, height)).unwrap();
        terminal
            .draw(|frame| {
                draw_panes(frame, frame.area(), app);
            })
            .unwrap();
        let buffer = terminal.backend().buffer();
        let rows = |start, end| {
            (0..height)
                .map(|y| {
                    (start..end)
                        .map(|x| buffer[(x, y)].symbol())
                        .collect::<String>()
                })
                .collect::<Vec<_>>()
        };
        (rows(0, width / 4), rows(width * 3 / 4, width))
    }

    #[test]
    fn side_pane_sessions_keep_current_eligible_row_visible_without_reordering() {
        let mut app = test_app();
        app.sessions = (0..100)
            .map(|index| {
                serde_json::from_value(serde_json::json!({
                    "id": format!("s{index}"), "name": format!("SESSION-{index:03}"),
                    "created_at":"", "updated_at":"", "archived": index % 3 == 0,
                }))
                .unwrap()
            })
            .collect();
        app.current = Some("s98".into());
        let before: Vec<_> = app
            .sessions
            .iter()
            .map(|session| (session.id.clone(), session.archived))
            .collect();
        for (width, height) in [(120, 24), (160, 12), (120, 40)] {
            let (left, _) = side_pane_regions(&mut app, width, height);
            let row = left
                .iter()
                .find(|row| row.contains("SESSION-098"))
                .expect("current Session visible");
            assert!(row.contains('●'), "{row}");
            assert_eq!(app.current.as_deref(), Some("s98"));
        }
        for id in ["s2", "missing", "s0"] {
            app.current = Some(id.into());
            let (left, _) = side_pane_regions(&mut app, 120, 24);
            let text = left.join("\n");
            assert!(text.contains("SESSION-001"), "{text}");
            assert!(
                !text.contains("SESSION-000"),
                "archived Sessions remain excluded"
            );
            if id == "s2" {
                assert!(left.iter().any(|row| row.contains("● SESSION-002")));
            }
        }
        assert_eq!(
            app.sessions
                .iter()
                .map(|session| (session.id.clone(), session.archived))
                .collect::<Vec<_>>(),
            before
        );
        app.sessions.truncate(3);
        let (left, _) = side_pane_regions(&mut app, 120, 24);
        assert!(left.join("\n").contains("SESSION-002"));
        for (width, height) in [(0, 0), (1, 1), (4, 2), (12, 4)] {
            side_pane_regions(&mut app, width, height);
        }
    }

    #[test]
    fn side_pane_activity_keeps_newest_wrapped_tail_visible_on_resize() {
        let mut app = test_app();
        app.notes = vec![
            "oldest ".repeat(15),
            "older ".repeat(18),
            format!("{}表👩🏽‍💻\nembedded note tail-END", "latest ".repeat(10)),
        ];
        let before = app.notes.clone();
        for (width, height) in [(80, 16), (120, 16), (160, 24), (80, 12)] {
            let (_, right) = side_pane_regions(&mut app, width, height);
            assert!(
                right.iter().any(|row| row.contains("tail-END")),
                "{right:?}"
            );
        }
        assert_eq!(app.notes, before);
        app.notes = vec!["FIRST".into(), "SECOND".into(), "THIRD".into()];
        let (_, right) = side_pane_regions(&mut app, 120, 24);
        let first = right.iter().position(|row| row.contains("FIRST")).unwrap();
        let second = right.iter().position(|row| row.contains("SECOND")).unwrap();
        let third = right.iter().position(|row| row.contains("THIRD")).unwrap();
        assert!(first < second && second < third);
        assert!(right[first].contains('·'));
        app.notes = vec![format!("{}hidden-after-cap", "x".repeat(120))];
        assert!(!side_pane_regions(&mut app, 120, 24)
            .1
            .join("\n")
            .contains("hidden-after-cap"));
        app.notes.clear();
        assert!(side_pane_regions(&mut app, 120, 24)
            .1
            .join("\n")
            .contains("Nothing yet."));
        for (width, height) in [(0, 0), (1, 1), (4, 2), (12, 4)] {
            side_pane_regions(&mut app, width, height);
        }
    }

    #[test]
    fn side_panes_resize_and_hide() {
        let mut app = test_app();
        app.multi_pane = true;
        app.slash("panes wider");
        assert_eq!(app.pane_widths, (25, 29));
        app.key(KeyEvent::new(
            KeyCode::Left,
            KeyModifiers::CONTROL | KeyModifiers::SHIFT,
        ));
        assert_eq!(app.pane_widths, (22, 26));
        app.slash("panes left");
        assert_eq!(app.pane_widths, (0, 26));
        // A hidden pane draws nothing and the chat takes its room.
        let screen = render(&mut app, 140, 30);
        assert!(!screen.contains("╭ Sessions"), "{screen}");
        app.slash("panes reset");
        assert!(render(&mut app, 140, 30).contains("╭ Sessions"));
        assert_eq!(pane_widths(&[0, 99]), (0, 40));
        assert_eq!(pane_widths(&[]), (22, 26));
        app.slash("panes sideways");
        assert!(app.notes.last().unwrap().starts_with("usage: /panes"));
    }

    fn list_wheel(app: &mut App, column: u16, row: u16, down: bool) {
        use crossterm::event::{MouseEvent, MouseEventKind};
        app.mouse(MouseEvent {
            kind: if down {
                MouseEventKind::ScrollDown
            } else {
                MouseEventKind::ScrollUp
            },
            column,
            row,
            modifiers: KeyModifiers::NONE,
        });
    }

    fn wheel_fixture_sessions(count: usize) -> Vec<SessionInfo> {
        (0..count)
            .map(|i| {
                serde_json::from_value(serde_json::json!({
                    "id": format!("s{i}"),
                    "name": format!("Session {i}"),
                    "archived": i % 2 == 0,
                    "created_at": "2026-01-01T00:00:00Z",
                    "updated_at": "2026-01-01T00:00:00Z"
                }))
                .unwrap()
            })
            .collect()
    }

    #[test]
    fn wheel_moves_filtered_sessions_and_reveals_selection_without_opening() {
        let mut app = test_app();
        app.view = View::Sessions;
        app.sessions = wheel_fixture_sessions(9);
        app.input_focus = true;
        assert_eq!(app.visible_sessions().len(), 4);
        let current = app.current.clone();
        let pending = app.pending.len();
        render(&mut app, 100, 9);
        let region = {
            let targets = app.click_targets.borrow();
            assert!(!targets.iter().any(|(_, hit)| hit == &Click::Session(3)));
            targets
                .iter()
                .find_map(|(r, hit)| (hit == &Click::Session(0)).then_some(*r))
                .unwrap()
        };
        list_wheel(&mut app, region.x, region.y, true);
        assert_eq!(app.session_idx, 3);
        list_wheel(&mut app, region.x, region.y, true);
        assert_eq!(app.session_idx, 3);
        render(&mut app, 100, 9);
        assert!(app
            .click_targets
            .borrow()
            .iter()
            .any(|(_, hit)| hit == &Click::Session(3)));
        list_wheel(&mut app, region.x, region.y, false);
        assert_eq!(app.session_idx, 0);
        assert_eq!(app.current, current);
        assert_eq!(app.pending.len(), pending);
        assert!(app.input_focus);
    }

