    #[test]
    fn t_runs_a_tool_by_hand_from_a_schema_skeleton() {
        let mut app = test_app();
        let tool = ToolInfo {
            id: "t".into(),
            name: "fetch_page".into(),
            title: String::new(),
            tags: Vec::new(),
            pinned: false,
            disabled: false,
            description: String::new(),
            retired: false,
            current_version: 1,
            capabilities: vec![],
            memory_mb: 64,
            invocations: 0,
            success_rate: None,
            needs_attention: false,
            created_at: String::new(),
            updated_at: String::new(),
            last_used_at: None,
            recent: String::new(),
            author: "agent".into(),
        };
        app.tools = vec![tool.clone()];
        app.tool_detail = Some(ToolDetail {
            description_review: Default::default(),
            description_reviews: Vec::new(),
            tool,
            versions: vec![ToolVersionInfo {
                version: 1,
                author: "agent".into(),
                created_at: String::new(),
                capabilities: vec![],
                memory_mb: 64,
                input_schema: r#"{"type":"object","properties":{"url":{"type":"string"}}}"#.into(),
                output_schema: "{}".into(),
                code: String::new(),
            }],
            metrics: Default::default(),
            optimiser_attempts: vec![],
            version_metrics: vec![],
            approval: None,
            recent_calls: vec![],
            listing_tokens: 0,
            uses: vec![],
            modules: vec![],
            used_by: vec![],
            example: Some(formless_protocol::ToolExample {
                version: 1,
                input: r#"{"repo":"/src/app"}"#.into(),
                output: r#"{"author":"ada"}"#.into(),
                created_at: chrono::Utc::now().to_rfc3339(),
            }),
            attention: vec![],
        });
        app.view = View::Tools;
        app.current = Some("s1".into());
        // The detail shows a real call as an example (SPEC §10.4).
        let screen = render(&mut app, 100, 30);
        assert!(screen.contains("Example"), "{screen}");
        assert!(screen.contains(r#"output    {"author":"ada"}"#), "{screen}");
        // Who calls it, and retiring it then takes a second x.
        app.tool_detail.as_mut().unwrap().used_by = vec!["summarise_page".into()];
        let screen = render(&mut app, 100, 30);
        assert!(screen.contains("used by summarise_page"), "{screen}");
        app.key(KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE));
        assert!(
            app.notes.last().unwrap().contains("Press x again"),
            "{:?}",
            app.notes.last()
        );
        assert_eq!(app.retire_arm.as_deref(), Some("t"));
        app.key(KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE));
        assert_eq!(app.retire_arm, None);
        app.tool_detail.as_mut().unwrap().used_by.clear();
        app.key(KeyEvent::new(KeyCode::Char('t'), KeyModifiers::NONE));
        let ed = app.editor.as_ref().expect("run editor");
        assert_eq!(ed.mode, EditMode::Run);
        assert_eq!(ed.text(), "{\n  \"url\": \"\"\n}");
        assert!(render(&mut app, 100, 20).contains("Run fetch_page"));
        // D and S edit the description and schemas instead.
        app.editor = None;
        app.key(KeyEvent::new(KeyCode::Char('D'), KeyModifiers::NONE));
        assert_eq!(app.editor.as_ref().unwrap().mode, EditMode::Description);
        app.editor = None;
        app.key(KeyEvent::new(KeyCode::Char('S'), KeyModifiers::NONE));
        let ed = app.editor.as_ref().unwrap();
        assert_eq!(ed.mode, EditMode::Schemas);
        assert!(ed.text().contains("\"input_schema\": {"), "{}", ed.text());
        assert!(render(&mut app, 100, 20).contains("fetch_page · schemas"));
        // Schemas must stay objects.
        app.editor.as_mut().unwrap().chars =
            r#"{"input_schema": 3, "output_schema": {}}"#.chars().collect();
        app.key(KeyEvent::new(KeyCode::Char('s'), KeyModifiers::CONTROL));
        assert!(app.notes.last().unwrap().contains("each a JSON object"));
        app.editor = None;
        app.key(KeyEvent::new(KeyCode::Char('t'), KeyModifiers::NONE));
        // Bad JSON stays in the editor.
        app.key(KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE));
        app.key(KeyEvent::new(KeyCode::Char('s'), KeyModifiers::CONTROL));
        assert!(app.editor.is_some());
        assert!(app.notes.last().unwrap().starts_with("not valid JSON"));
        app.key(KeyEvent::new(KeyCode::Backspace, KeyModifiers::NONE));
        app.key(KeyEvent::new(KeyCode::Char('s'), KeyModifiers::CONTROL));
        assert!(app.editor.is_none());
        // The result comes back in the pager.
        let (tx, rx) = mpsc::channel();
        app.inbox = Some(rx);
        app.pending.insert(5, Pending::RunTool);
        tx.send(ServerMessage::Response {
            id: 5,
            ok: true,
            result: Some(serde_json::json!({"result": "{\"title\":\"Example\"}"})),
            error: None,
        })
        .unwrap();
        app.drain_daemon();
        let pager = app.pager.as_ref().expect("pager");
        assert!(pager
            .lines
            .iter()
            .any(|l| l.contains("\"title\": \"Example\"")));
    }

    #[test]
    fn quit_dialog_reserves_wrapped_warning_and_all_action_labels() {
        let mut app = test_app();
        for count in [1, 2] {
            app.running_sessions = (0..count).map(|index| format!("private-{index}")).collect();
            for (width, height) in [(80, 24), (120, 24), (40, 24), (80, 5), (40, 7)] {
                let mut terminal =
                    Terminal::new(ratatui::backend::TestBackend::new(width, height)).unwrap();
                terminal
                    .draw(|frame| draw_quit_confirm(frame, &app))
                    .unwrap();
                let buffer = terminal.backend().buffer();
                let screen = (0..height)
                    .map(|y| {
                        (0..width)
                            .map(|x| buffer[(x, y)].symbol())
                            .collect::<String>()
                    })
                    .collect::<Vec<_>>()
                    .join(" ");
                let text = screen
                    .chars()
                    .filter(|c| !"╭╮╰╯─│".contains(*c))
                    .collect::<String>()
                    .split_whitespace()
                    .collect::<Vec<_>>()
                    .join(" ");
                let warning = format!(
                    "{count} Run{} still working in the daemon. {} keep going if you quit.",
                    if count == 1 { " is" } else { "s are" },
                    if count == 1 { "It will" } else { "They'll" }
                );
                assert!(text.contains(&warning), "{width}x{height}: {text}");
                assert!(
                    text.contains("q quit s stop them and quit Esc cancel"),
                    "{width}x{height}: {text}"
                );
                assert!(!text.contains("Resize"));
            }
        }
        for (width, height) in [(80, 4), (20, 4), (12, 3), (1, 1)] {
            let mut terminal =
                Terminal::new(ratatui::backend::TestBackend::new(width, height)).unwrap();
            terminal
                .draw(|frame| draw_quit_confirm(frame, &app))
                .unwrap();
            let screen = terminal
                .backend()
                .buffer()
                .content
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>();
            if width >= 20 {
                assert!(
                    screen.contains("Resize") && screen.contains("Esc cancel"),
                    "{screen}"
                );
            } else if width >= 12 {
                assert!(screen.contains("Esc"));
            }
        }
    }

    #[test]
    fn finite_proposal_score_ties_are_neutral_without_changing_status_or_rounding() {
        for (theme_name, color) in [("dark", true), ("dark", false), ("colorblind", true)] {
            let mut app = test_app();
            let _theme = theme::test_theme(theme_name);
            app.color = color;
            app.view = View::Proposals;
            for (candidate, baseline, expected) in [
                (Some(0.5), Some(0.5), "50% vs 50%"),
                (Some(0.50001), Some(0.5), "ok 50% vs 50%"),
                (Some(0.49999), Some(0.5), "fail 50% vs 50%"),
                (None, Some(0.5), "unmeasured"),
                (
                    Some(f64::INFINITY),
                    Some(f64::INFINITY),
                    "fail inf% vs inf%",
                ),
            ] {
                app.proposals = vec![PromptProposalInfo {
                    id: "fixture".into(),
                    kind: "prompt".into(),
                    content: "private proposal".into(),
                    rationale: "เหตุผล 日本語".into(),
                    status: "measured".into(),
                    baseline_score: baseline,
                    candidate_score: candidate,
                    eval_total: 20,
                    est_tokens: 1,
                    created_at: String::new(),
                    applied_at: None,
                }];
                let screen = render(&mut app, 160, 24);
                let row = screen
                    .lines()
                    .find(|line| line.contains("private proposal"))
                    .unwrap();
                let row = row.split_whitespace().collect::<Vec<_>>().join(" ");
                let redundant = theme::redundant(color);
                assert_eq!(redundant, !color || theme_name == "colorblind");
                let expected = if redundant {
                    expected.to_owned()
                } else {
                    expected
                        .trim_start_matches("ok ")
                        .trim_start_matches("fail ")
                        .to_owned()
                };
                assert!(row.contains(&expected), "{theme_name}/{color}: {row}");
                if candidate == Some(0.5) && baseline == Some(0.5) {
                    assert!(
                        !row.contains("fail 50%") && !row.contains("ok 50%"),
                        "{row}"
                    );
                }
                assert!(
                    row.contains("measured")
                        && row.contains("เหตุผล")
                        && row.replace(' ', "").contains("日本語")
                );
            }
        }
    }

    #[test]
    fn enter_reviews_a_proposal_and_decides_from_the_diff() {
        let mut app = test_app();
        app.view = View::Proposals;
        app.proposals = vec![PromptProposalInfo {
            id: "p1".into(),
            kind: "prompt".into(),
            content: "Check the output schema.".into(),
            rationale: "fewer invalid outputs".into(),
            status: "measured".into(),
            baseline_score: Some(0.5),
            candidate_score: Some(0.8),
            eval_total: 20,
            est_tokens: 12,
            created_at: String::new(),
            applied_at: None,
        }];
        let key = |c| KeyEvent::new(c, KeyModifiers::NONE);
        app.key(key(KeyCode::Enter));
        assert_eq!(app.reviewing.as_deref(), Some("p1"));
        app.show_proposal_diff(&serde_json::json!({
            "target": "learned guidance",
            "applied": false,
            "diff": [[" ", "Learned guidance (v1): Prefer existing Tools."],
                     ["+", "Learned guidance (v2): Check the output schema."]],
        }));
        let screen = render(&mut app, 120, 30);
        assert!(
            screen.contains("candidate 80% vs baseline 50% over 20 runs"),
            "{screen}"
        );
        assert!(screen.contains("+ Learned guidance (v2)"), "{screen}");
        assert!(screen.contains("a apply · r reject"), "{screen}");
        // r rejects from the review and closes it.
        app.key(key(KeyCode::Char('r')));
        assert!(app.pager.is_none() && app.reviewing.is_none());
        assert!(app.notes.iter().any(|n| n == "rejected the proposal"));
    }

    #[test]
    fn relay_shows_the_pairing_link_as_a_qr_code() {
        let mut app = test_app();
        std::fs::create_dir_all(&app.paths.config_dir).unwrap();
        std::fs::create_dir_all(&app.paths.data_dir).unwrap();
        app.slash("relay");
        assert!(app.pager.is_none(), "off: nothing to pair");
        let mut cfg = Config::default();
        cfg.relay.enabled = true;
        cfg.save(&app.paths).unwrap();
        let secret = formless_core::config::generate_relay_secret();
        std::fs::write(app.paths.relay_secret_file(), &secret).unwrap();
        app.slash("relay");
        let pager = app.pager.as_ref().expect("pager");
        assert_eq!(pager.title, "Pair a device");
        assert!(pager
            .lines
            .iter()
            .any(|l| l.contains(&format!("#k={secret}"))));
        assert!(pager.lines.iter().any(|l| l.contains("pairing secret")));
        assert!(
            pager
                .lines
                .iter()
                .filter(|l| l.contains('▀') || l.contains('▄'))
                .count()
                > 5
        );
    }

