    #[test]
    fn compact_usage_units_promote_without_changing_exact_counts_cost_or_percentages() {
        for (count, expected) in [
            (i64::MIN, "-9223372036854775808"),
            (-1000, "-1000"),
            (0, "0"),
            (999, "999"),
            (1000, "1.0k"),
            (999_949, "999.9k"),
            (999_950, "1.0M"),
            (999_999, "1.0M"),
            (1_000_000, "1.0M"),
            (12_345_678, "12.3M"),
            (999_949_999, "999.9M"),
            (999_950_000, "1.0B"),
            (1_000_000_000, "1.0B"),
            (12_345_678_901, "12.3B"),
            (i64::MAX, "9223372036.9B"),
        ] {
            assert_eq!(short_count(count), expected, "{count}");
        }
        for count in [-5000, -1, 0, 1, 999, 1000, 12345, 999_900, 999_949] {
            let prior = if count >= 1000 {
                format!("{:.1}k", count as f64 / 1000.0)
            } else {
                count.to_string()
            };
            assert_eq!(short_count(count), prior);
        }
        let usage = UsageInfo {
            steps: 3,
            prompt_tokens: 999_999,
            completion_tokens: 12_345_678,
            cached_tokens: 400_000,
            cache_write_tokens: 1_000_000,
            cost: Some(1.23456),
            memories: 2,
            ..Default::default()
        };
        let expected="3 steps · 1.0M in / 12.3M out · 40% cached · 1.0M written to cache · $1.235 · used 2 memories (/memory used)";
        assert_eq!(usage_text(&usage), expected);
        let mut app = test_app();
        app.current = Some("s1".into());
        app.run_usage.insert("s1".into(), usage.clone());
        let mut terminal = Terminal::new(ratatui::backend::TestBackend::new(300, 1)).unwrap();
        terminal
            .draw(|frame| draw_status(frame, frame.area(), &app, None))
            .unwrap();
        let status = terminal
            .backend()
            .buffer()
            .content
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(status.contains(expected), "{status}");
        let (client, sent) = DaemonClient::recording();
        let (tx, inbox) = mpsc::channel();
        app.client = Some(client);
        app.inbox = Some(inbox);
        app.slash("usage");
        let request: RequestEnvelope = serde_json::from_str(&sent.try_recv().unwrap()).unwrap();
        assert!(matches!(request.request, Request::SessionUsage { .. }));
        tx.send(ServerMessage::Response {
            id: request.id,
            ok: true,
            result: Some(serde_json::json!({"last_run":usage,"total":usage,"runs":2})),
            error: None,
        })
        .unwrap();
        app.drain_daemon();
        assert!(app.notes.contains(&format!("last Run: {expected}")));
        assert!(app.notes.contains(&format!("session (2 Runs): {expected}")));
        assert_eq!(app.run_usage["s1"], usage);
    }

    #[test]
    fn metrics_chart_tokens_and_cost_by_day_or_key() {
        let mut app = test_app();
        app.view = View::Metrics;
        let row = |key: &str, p, c, cost| UsageRow {
            key: key.into(),
            prompt_tokens: p,
            completion_tokens: c,
            cached_tokens: p / 2,
            cost,
        };
        app.usage_rows = vec![
            row("2026-10-21", 1_200_000, 300_000, Some(1.25)),
            row("2026-10-22", 400_000, 100_000, Some(0.5)),
        ];
        let screen = render(&mut app, 120, 40);
        assert!(
            screen.contains("Tokens by day (b) · 2.0M tok · $1.75"),
            "{screen}"
        );
        let day = screen
            .lines()
            .find(|line| line.contains("2026-10-21"))
            .unwrap();
        let bar = day
            .split_once("2026-10-21 ")
            .unwrap()
            .1
            .split_whitespace()
            .next()
            .unwrap();
        let mut components: Vec<char> = bar.chars().collect();
        components.dedup();
        assert_eq!(
            components,
            ['░', '▒', '█'],
            "cached, fresh and completion must remain distinct and ordered: {day}"
        );
        assert!(
            screen.contains("░cached / ▒fresh / █completion"),
            "{screen}"
        );
        assert!(screen.contains("1.5M tok  $1.25"), "{screen}");
        app.key(KeyEvent::new(KeyCode::Char('b'), KeyModifiers::NONE));
        app.usage_rows = vec![row("deepseek-flash", 10, 5, None)];
        let screen = render(&mut app, 120, 40);
        assert!(screen.contains("Tokens by model (b) · 15 tok "), "{screen}");
    }

    #[test]
    fn c_groups_the_tools_list_and_z_folds_a_group() {
        let tool = |name: &str, cap: &str| ToolInfo {
            id: name.into(),
            name: name.into(),
            title: String::new(),
            tags: Vec::new(),
            pinned: false,
            disabled: false,
            description: String::new(),
            retired: false,
            current_version: 1,
            capabilities: vec![cap.into()],
            memory_mb: 64,
            invocations: 1,
            success_rate: Some(1.0),
            needs_attention: false,
            created_at: String::new(),
            updated_at: String::new(),
            last_used_at: None,
            recent: String::new(),
            author: "agent".into(),
        };
        let mut app = test_app();
        app.tools = vec![
            tool("read_file", "fs:read:/tmp"),
            tool("http_get", "net:example.com"),
        ];
        app.view = View::Tools;
        let key = |c| KeyEvent::new(KeyCode::Char(c), KeyModifiers::NONE);
        app.key(key('c'));
        let screen = render(&mut app, 140, 30);
        assert!(screen.contains("by capability"), "{screen}");
        assert!(
            screen.contains("▾ fs (1)") && screen.contains("▾ net (1)"),
            "{screen}"
        );
        let (_, area) = app.list_wheel_region.get().unwrap();
        let pending = app.pending.len();
        list_wheel(&mut app, area.x + 1, area.bottom(), true);
        assert_eq!(app.tool_idx, 0, "details pane does not move selection");
        list_wheel(&mut app, area.x + 1, area.y + 2, true);
        assert_eq!(app.selected_tool().unwrap().name, "http_get");
        assert!(app.tool_detail.is_none());
        assert_eq!(app.pending.len(), pending);
        list_wheel(&mut app, area.x + 1, area.y + 2, false);
        assert_eq!(app.selected_tool().unwrap().name, "read_file");
        // The first Tool (fs) is selected; z folds its group.
        app.key(key('z'));
        let screen = render(&mut app, 140, 30);
        assert!(screen.contains("▸ fs (1)"), "{screen}");
        assert!(!screen.contains("read_file"), "{screen}");
        assert_eq!(app.selected_tool().unwrap().name, "http_get");
        app.key(key('Z'));
        assert!(render(&mut app, 140, 30).contains("read_file"));
    }

