    #[test]
    fn live_calls_render_as_a_tree_and_fold_finished_subtrees() {
        let node = |name: &str, depth: usize, status: &str| LiveToolCall {
            metadata_pending: false,
            invocation_id: None,
            name: name.into(),
            depth,
            subagent: None,
            version: 1,
            arguments: String::new(),
            status: status.into(),
            started: Instant::now(),
            elapsed_ms: Some(5),
            handle: None,
            stalled_secs: None,
            progress: None,
        };
        let calls = vec![
            node("done_top", 0, "ok"),
            node("outer", 0, "running"),
            node("fetch", 1, "ok"),
            node("parse", 2, "ok"),
            node("parse2", 2, "ok"),
            node("store", 1, "failed"),
            node("retry", 2, "running"),
        ];
        let shown: Vec<(String, usize)> = live_tree(&calls)
            .into_iter()
            .map(|(c, folded)| (c.name.clone(), folded))
            .collect();
        assert_eq!(
            shown,
            vec![
                ("outer".to_string(), 0),
                ("fetch".to_string(), 2),
                ("store".to_string(), 0),
                ("retry".to_string(), 0),
            ],
            "finished top-level calls hide; ok subtrees fold; failed ones stay open"
        );
    }

    #[test]
    fn ctrl_c_clears_then_detaches_on_a_second_press() {
        let mut app = test_app();
        let ctrl_c = KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL);
        app.input = "half-typed".into();
        app.key(ctrl_c);
        assert!(
            app.input.is_empty() && !app.should_quit,
            "first press clears"
        );
        app.key(ctrl_c);
        assert!(app.should_quit, "second press within the window detaches");

        let mut app = test_app();
        app.key(ctrl_c);
        assert!(!app.should_quit);
        assert!(app.notes.last().unwrap().contains("again to detach"));
        app.ctrl_c_at = Some(Instant::now() - CTRL_C_WINDOW);
        app.key(ctrl_c);
        assert!(!app.should_quit, "an expired first press only re-arms");
        app.key(ctrl_c);
        assert!(app.should_quit);
    }

    /// Releases are ignored; presses insert once and repeats repeat (#792).
    #[test]
    fn key_releases_do_nothing() {
        let mut app = test_app();
        let ev = |c, kind| KeyEvent::new_with_kind(KeyCode::Char(c), KeyModifiers::NONE, kind);
        for c in "สวัสดี".chars() {
            app.key(ev(c, KeyEventKind::Release));
        }
        assert!(app.input.is_empty(), "releases insert nothing");
        for c in "สวัสดี".chars() {
            app.key(ev(c, KeyEventKind::Press));
            app.key(ev(c, KeyEventKind::Release));
        }
        assert_eq!(&*app.input, "สวัสดี");
        app.key(ev('!', KeyEventKind::Press));
        app.key(ev('!', KeyEventKind::Repeat));
        assert!(app.input.ends_with("!!"));
    }

